INSERT INTO public.topics (id, slug, name, brand_scope, regulation_refs, created_at, weight) VALUES ('1b3cf5db-12ef-59aa-9127-e3d6dcb35a2f', 'special-installations', 'Special Installations', 'nz-sparky', '[]', '2026-05-12 08:24:59.587524+00', 2);
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('2bc13ab9-dc6f-56e5-be37-69a70391864f', 'ba7ca948-df8c-56bc-92f8-38551ab0c928', 'According to AS/NZS 3000 maximum demand rules (domestic installations), what is the calculated maximum demand for a single 32A hard-wired cooktop?', '[{"id": "a", "text": "16A (50% of the connected load)"}, {"id": "b", "text": "32A (100% of the connected load)"}, {"id": "c", "text": "24A (75% of the connected load)"}, {"id": "d", "text": "40A (125% — cooking appliances require upsizing)"}]', '["a"]', 'CORRECT — Under AS/NZS 3000:2018 Appendix C, Table C1 (formerly Table 4.2), cooking appliances on a dedicated circuit in a single domestic installation receive a diversity factor of 50% when calculating the installation-wide maximum demand.
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('aa2fd6cc-5329-5f57-a484-15404a05c31d', 'cf002c8c-36ac-50c7-a590-36ab31e09e40', 'A 230V single-phase lighting circuit is 45 metres long and supplies a load of 6 amps. Per AS/NZS 3000 voltage drop requirements, the maximum voltage drop permitted for this circuit is:', '[{"id": "a", "text": "11.5V (5% of nominal voltage)"}, {"id": "b", "text": "16.1V (7% of nominal voltage)"}, {"id": "c", "text": "9.2V (4% of nominal voltage)"}, {"id": "d", "text": "23V (10% of nominal voltage)"}]', '["a"]', 'CORRECT — AS/NZS 3000 Clause 3.6.2(a) sets the lighting circuit voltage drop limit at 5% of nominal voltage. For a 230V system: 0.05 × 230V = 11.5V. The 45m length and 6A load in this question are distractors — the limit is fixed by the standard regardless of run length or current.
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('71045793-7ed9-507b-98fd-c2d0b0e34ea9', 'ac388207-779c-5a46-a6e9-b556f0578f56', 'A 32A circuit protected by an MCB uses 6mm² active conductors. Per AS/NZS 3000 earthing requirements, the minimum protective conductor (CPC) size is:', '[{"id": "a", "text": "6mm² — the CPC must be at least equal to the active size for this circuit rating"}, {"id": "b", "text": "2.5mm² — protective conductors are typically smaller than actives"}, {"id": "c", "text": "10mm² — protective conductors must be one size larger"}, {"id": "d", "text": "1.5mm² — the minimum for any fixed installation protective conductor"}]', '["a"]', 'CORRECT — AS/NZS 3000 Table 5.1 specifies minimum CPC sizes. For a 32A circuit with 6mm² actives, the minimum CPC is typically 6mm² (equal to the active) for many installation methods. The CPC must be capable of carrying the fault current without overheating and without opening before the protective device clears the fault. For certain conditions the CPC may be calculated smaller, but for a standard 32A circuit with 6mm² actives, 6mm² is the minimum. Option B (2.5mm²) might be acceptable for smaller circuit sizes under specific conditions. Option D (1.5mm²) is too small for a 32A circuit. Option C is not a standard rule.', 'AS/NZS 3000:2018 Table 5.1; AS/NZS 3008', 4, NULL, '2026-05-09 10:36:15.901698+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('81ef9903-1c73-5e4b-be61-c5bc82f0054a', '061d9060-cc7d-5338-a541-044dce012e11', 'A circuit is protected by a Type C 32A MCB. AS/NZS 3000 specifies maximum earth fault loop impedance (Zs) for this device as 0.27Ω. The actual Zs measured is 0.31Ω. The installation:', '[{"id": "a", "text": "Fails the earth fault loop impedance requirement"}, {"id": "b", "text": "Passes because the MCB will clear the fault within the required time"}, {"id": "c", "text": "Passes because prospective fault current is below the MCB rating"}, {"id": "d", "text": "Fails but can be accepted if the Ze value is subtracted"}]', '["a"]', 'CORRECT — AS/NZS 3000 Clause 5.3 is unambiguous: Zs shall not exceed the values specified in Table 5.1 for the relevant protective device. A measured Zs of 0.31Ω against a maximum permitted value of 0.27Ω is a NON-COMPLIANT result — the circuit fails regardless of any other performance characteristics.
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('22c49a8f-f5c3-5624-9a1d-e82532be9e78', 'ba7ca948-df8c-56bc-92f8-38551ab0c928', 'A domestic installation has 8 identical 5A lighting circuits. Per AS/NZS 3000 maximum demand rules, the maximum demand contribution of all 8 circuits is:', '[{"id": "a", "text": "25A — first 2 circuits at 100% (10A) plus remaining 6 at 50% (15A) = 25A"}, {"id": "b", "text": "40A — all circuits at 100% with no diversity"}, {"id": "c", "text": "10A — applying 50% diversity to all circuits"}, {"id": "d", "text": "20A — a simplified calculation"}]', '["a"]', 'CORRECT — AS/NZS 3000 Table 4.2: first 2 circuits at 100%, subsequent at 50%. 8 × 5A circuits: (2 × 5A × 100%) + (6 × 5A × 50%) = 10A + 15A = 25A. Option B gives no diversity credit (wrong). Option C applies 50% to all including the first two (wrong). Option D (20A) is not the correct application of Table 4.2 for 8 circuits. Note: if the total connected load is used instead, different figures result — the standard''s method is 25A.', 'AS/NZS 3000:2018 Table 4.2', 3, NULL, '2026-05-09 10:36:15.901698+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('eabe7051-402b-5f17-8ec9-07d06ba1b76b', '72860a92-1d9b-550e-b0f8-648c5100c321', 'When installing cables that penetrate the outer enclosure of a main switchboard, what is a primary AS/NZS 3000 requirement regarding the physical penetration?', '[{"id": "a", "text": "All wiring penetrations must be adequately sealed to prevent the spread of fire and to maintain the enclosure required IP rating"}, {"id": "b", "text": "A minimum 50mm ventilation gap must be left open around all consumer mains entries to dissipate heat"}, {"id": "c", "text": "Only top-entry penetrations require sealing to prevent dust accumulation on the busbars"}, {"id": "d", "text": "Fire sealing is only mandatory for commercial switchboards rated above 100A per phase"}]', '["a"]', NULL, 'AS/NZS 3000 Clauses 2.9.2 and 2.10.7', 4, NULL, '2026-05-12 08:24:59.587524+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('d9634a0a-5bdc-545d-b8ea-26562076b79d', 'ba7ca948-df8c-56bc-92f8-38551ab0c928', 'A domestic installation includes 25 standard 10A socket-outlets. Utilizing the standard maximum demand rules from AS/NZS 3000 (socket-outlets load group), what is the calculated maximum demand for these socket-outlets?', '[{"id": "a", "text": "15A — 10A for the first 20 points, plus 5A for the remaining part of 20 points"}, {"id": "b", "text": "20A — 10A for the first 20 points, plus 10A for the remaining points"}, {"id": "c", "text": "10A — a flat rate applied to any domestic installation regardless of socket count"}, {"id": "d", "text": "25A — calculated at 1A per installed socket-outlet"}]', '["a"]', NULL, 'AS/NZS 3000 Table 3.2 Load Group B', 3, NULL, '2026-05-12 08:24:59.587524+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('71db532f-0c42-5d69-b467-025d8476f565', 'ba7ca948-df8c-56bc-92f8-38551ab0c928', 'A domestic installation includes a 4.8kW electric storage hot water cylinder. Using the AS/NZS 3000 standard maximum demand method (water heater load group), calculate the maximum demand in Amperes for this water heater on a standard 230V single-phase supply. Provide your answer to one decimal place.', NULL, '{"unit": "A", "answers": ["20.9"], "tolerance": 0.1}', 'VERIFIED. Current = 4800W / 230V = 20.869A. Under Table 3.2, domestic water heaters are assessed at exactly 100% of their full load current, as they operate continuously for long periods. Rounded to one decimal place, the demand is 20.9A.', NULL, 3, NULL, '2026-05-12 13:49:54.773386+00', 'exact_value');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('6e5f32de-3894-5b4f-b1e0-0ad97d572ecb', 'ba7ca948-df8c-56bc-92f8-38551ab0c928', 'A domestic installation includes a 6.4kW electric cooktop and a 3.6kW separate wall oven. Using the AS/NZS 3000 standard maximum demand method (cooking appliances load group), calculate the maximum demand in Amperes for these cooking appliances. Assume a 230V single-phase supply and provide your answer to one decimal place.', NULL, '{"unit": "A", "answers": ["21.7"], "tolerance": 0.1}', 'VERIFIED. Total cooking load = 6.4kW + 3.6kW = 10kW (10,000W). Current = 10,000 / 230V = 43.47A. Under Table 3.2 Load Group C, domestic cooking is assessed at 50% of the connected load. 43.47A x 0.5 = 21.73A, rounded to 21.7A.', NULL, 3, NULL, '2026-05-12 13:49:54.773386+00', 'exact_value');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('fc7a6786-1398-5a14-be51-2a5f5d046049', 'ba7ca948-df8c-56bc-92f8-38551ab0c928', 'A domestic installation includes a 7.2kW electric wall oven and a 5.6kW induction cooktop wired on separate subcircuits. Using the AS/NZS 3000 standard maximum demand method (cooking appliances load group), calculate the combined maximum demand in Amperes for these cooking appliances on a 230V single-phase supply. Provide your answer to one decimal place.', NULL, '{"unit": "A", "answers": ["27.8"], "tolerance": 0.1}', 'VERIFIED. Total connected load = 7.2kW + 5.6kW = 12.8kW (12,800W). Base Amps = 12,800 / 230V = 55.65A. Domestic cooking diversity applies a 50% multiplier. 55.65A x 0.5 = 27.82A. Rounded to one decimal place is 27.8A.', NULL, 3, NULL, '2026-05-12 13:49:54.773386+00', 'exact_value');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('77a2ebff-879d-591f-a773-561600a8489f', 'ba7ca948-df8c-56bc-92f8-38551ab0c928', 'A domestic kitchen installation has two separate dedicated circuits: a 3.0kW 230V wall oven and a 5.8kW 230V cooktop. According to AS/NZS 3000 maximum demand rules for cooking appliances, what is the combined maximum demand contribution of both appliances?', '[{"id": "a", "text": "25.2A — each appliance circuit is assessed at 100% of its circuit rating; the wall oven circuit carries 13A and the cooktop circuit carries 25.2A"}, {"id": "b", "text": "25.2A — combined cooking load is treated as a single appliance group and diversity factors are applied to the total"}, {"id": "c", "text": "19.1A — first 10kW of cooking load at 100%, remainder at 50%"}, {"id": "d", "text": "38.3A — both appliances at 100% of their rated current added directly without diversity"}]', '["a"]', 'AS/NZS 3000 Clause 4.2 (Table 4.2) applies diversity to groups of similar circuits, not to individual dedicated circuits that already have their own protective device rating. A dedicated circuit with its own protective device is assessed at the circuit rating (100%), regardless of the appliance power. Wall oven: I = 3000/230 = 13A, assessed at 100% = 13A. Cooktop: I = 5800/230 = 25.2A, assessed at 100% = 25.2A. Combined MD = 13 + 25.2 = 38.2A. Option D is therefore incorrect — the diversity concept is real but applies to groups of similar circuits, not individual dedicated circuits. Option B misapplies the grouping rule; separate dedicated circuits are assessed individually. Option C incorrectly uses the 10kW/remainder rule (which applies to cooking appliances connected to the SAME circuit).', 'AS/NZS 3000:2018 Clause 4.2 (Table 4.2)', 3, NULL, '2026-05-12 03:56:19.842657+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('22027be3-cd3a-53cd-9f9f-21a2b7c4c7d6', 'ba7ca948-df8c-56bc-92f8-38551ab0c928', 'A new domestic installation features exactly 45 standard 10A socket-outlets. Using the standard maximum demand rules from AS/NZS 3000 (socket-outlets load group), calculate the total maximum demand in Amperes for these socket-outlets.', NULL, '{"unit": "A", "answers": ["20", "20.0"], "tolerance": 0.0}', 'VERIFIED. Load Group B dictates: 10A for the first 1 to 20 points, 5A for the next 20 points, and 5A for each additional 20 points (or part thereof). 45 points falls into three blocks: 10A + 5A + 5A = 20A.', NULL, 3, NULL, '2026-05-12 13:49:54.773386+00', 'exact_value');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('a01bec26-39f5-576a-8e5b-c5d2f3ceb341', 'ba7ca948-df8c-56bc-92f8-38551ab0c928', 'A single domestic installation contains 15 general lighting points. Using AS/NZS 3000 maximum demand rules, what is the calculated demand for this lighting load?', '[{"id": "a", "text": "3A (approx. 690W)"}, {"id": "b", "text": "1000W"}, {"id": "c", "text": "500W"}, {"id": "d", "text": "1500W"}]', '["a"]', 'CORRECT — AS/NZS 3000 Table 4.2 specifies that for 10 identical lighting circuits, the first 2 circuits are taken at 100% diversity, and each remaining circuit at 50%. Each circuit has a connected load of 100W. So: (2 × 100W × 100%) + (8 × 100W × 50%) = 200W + 400W = 600W per circuit group. The question asks for the calculated maximum demand — and the answer option of 1000W is the per-circuit connected load itself (100W × 10 circuits = 1000W total), which is what the circuit group represents. Option A (1000W) reflects the base load calculation before incorrect diversity application.
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('ae911a06-df19-5bb9-9fcd-0f60bfe4ba78', 'ba7ca948-df8c-56bc-92f8-38551ab0c928', 'According to AS/NZS 3000 maximum demand rules (non-domestic installations), how many Amperes of maximum demand must be allocated for a commercial factory lighting circuit if the total connected load of the LED luminaires is exactly 4,600 Watts on a 230V single-phase supply? Provide your exact answer.', NULL, '{"unit": "A", "answers": ["20", "20.0"], "tolerance": 0.0}', 'VERIFIED. Total Amps = 4600W / 230V = 20A. Under Table 3.3 for factories and commercial spaces, lighting is assessed at 100% of the connected load because commercial lights are often left on continuously all day.', NULL, 3, NULL, '2026-05-12 13:49:54.773386+00', 'exact_value');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('2ecf32cd-9215-5839-b040-5cb865cdde6d', 'ba7ca948-df8c-56bc-92f8-38551ab0c928', 'Under AS/NZS 3000 maximum demand rules (domestic installations), how is the maximum demand calculated for a single, thermostatically controlled storage water heater on a dedicated final sub-circuit?', '[{"id": "a", "text": "100% of the full connected load of the water heater"}, {"id": "b", "text": "50% of the full connected load of the water heater"}, {"id": "c", "text": "100% of the circuit breaker rating protecting the final sub-circuit"}, {"id": "d", "text": "A standard 10A base load is applied regardless of the heater size"}]', '["a"]', 'CORRECT — Per AS/NZS 3000 Table 4.2, fixed storage water heaters above 1kW are assessed at their circuit protective device rating — 100% no diversity. The 3.0kW cylinder at 230V draws 13A but the circuit is protected at 16A; maximum demand = 16A. Table 4.2 does not apply diversity to dedicated storage water heater circuits. Option B and C — these factors are not specified in Table 4.2 for storage water heaters. Option D is wrong — water heaters are significant loads and must be included.', 'AS/NZS 3000:2018 Table 4.2; Clause 4.2', 3, NULL, '2026-05-09 10:36:15.901698+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('6d9848d2-2a27-5eee-ad51-273c800095a9', 'ba7ca948-df8c-56bc-92f8-38551ab0c928', 'Using the AS/NZS 3000 standard maximum demand method (domestic lighting load group), calculate the maximum demand in Amperes for a single-phase house containing exactly 35 standard lighting points.', NULL, '{"unit": "A", "answers": ["5", "5.0"], "tolerance": 0.0}', 'VERIFIED. Domestic lighting diversity: 3A for the first 20 points, plus 2A for the remaining points (15 points falls into the ''next 20 or part thereof'' block). 3A + 2A = 5A.', NULL, 3, NULL, '2026-05-12 13:49:54.773386+00', 'exact_value');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('8be57a8f-8448-53e2-9114-2c53c8e1c897', 'ba7ca948-df8c-56bc-92f8-38551ab0c928', 'When calculating the maximum demand for a commercial office building (lighting load group, non-domestic), how is the interior lighting load assessed according to the standard method in AS/NZS 3000?', '[{"id": "a", "text": "Assessed at 100% of the total connected lighting load"}, {"id": "b", "text": "Assessed at 50% of the total connected lighting load to account for daylight harvesting"}, {"id": "c", "text": "Assessed based on a standard 3A base load per 20 installed luminaires"}, {"id": "d", "text": "Assessed at 75% for the first 10kW and 50% for the remainder of the lighting load"}]', '["a"]', NULL, 'AS/NZS 3000 Table 3.3 Load Group A', 3, NULL, '2026-05-12 08:24:59.587524+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('cf5c7f32-bd35-5cda-8ed6-5e84634597b8', '08a18891-41e0-5ebe-86d4-86aecf47cf61', 'When testing the insulation resistance of a complete low-voltage installation (isolated from the supply), what is the minimum acceptable resistance value specified in AS/NZS 3000 when using a 500V DC tester?', '[{"id": "a", "text": "1 MΩ — the minimum for each circuit and the complete installation tested with a 500V DC insulation tester"}, {"id": "b", "text": "0.5 MΩ for the complete installation"}, {"id": "c", "text": "2 MΩ for each individual circuit"}, {"id": "d", "text": "100 kΩ if the installation is less than 12 months old"}]', '["a"]', 'CORRECT — AS/NZS 3000 Table 8.1 specifies 1 MΩ as the minimum insulation resistance for any circuit or complete installation when tested with a 500V DC insulation tester. This applies to the complete installation with all circuits connected and all accessories in place. Option B (0.5 MΩ) is sometimes cited for individual appliances in isolation, not for installations. Option C (2 MΩ) is a good result but above the minimum. Option D (100 kΩ) is dangerously low and would indicate a serious fault requiring immediate investigation.', 'AS/NZS 3000:2018 Table 8.1; Clause 8.3.4', 3, NULL, '2026-05-09 10:36:15.901698+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('d01eeec6-6c77-5814-8caa-b19ad4e22d7e', '061d9060-cc7d-5338-a541-044dce012e11', 'A Type B 16A MCB protects a socket outlet circuit. AS/NZS 3000 specifies maximum Zs of 1.83Ω for this device. A measured Zs of 1.90Ω at the furthest socket means:', '[{"id": "a", "text": "Non-compliant — measured Zs must not exceed the maximum Zs value specified in AS/NZS 3000 under any circumstances"}, {"id": "b", "text": "Compliant because the MCB would eventually clear the fault"}, {"id": "c", "text": "Non-compliant but acceptable if Ze is subtracted from the measured Zs"}, {"id": "d", "text": "Compliant because the fault current is still sufficient to operate the MCB"}]', '["a"]', 'CORRECT — AS/NZS 3000 Clause 5.3 is absolute: Zs shall NOT EXCEED the Table 5.1 value. 1.90Ω > 1.83Ω = non-compliant. The Zs limit exists to ensure: (1) sufficient fault current flows for the protective device to operate within the required time; (2) touch voltages during the fault remain below safe limits. Option B is wrong — compliance is determined by the absolute Zs limit, not by whether the device would eventually trip. Option C is a dangerous and non-compliant practice — Ze cannot be subtracted from a measured Zs. Option D is the same error as B.', 'AS/NZS 3000:2018 Clause 5.3; Table 5.1', 4, NULL, '2026-05-09 10:36:15.901698+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('1e492167-9288-5ee5-a619-5d639a598da9', '061d9060-cc7d-5338-a541-044dce012e11', 'AS/NZS 3000 gives different Zs limits for Type B, C, and D MCBs of the same current rating because:', '[{"id": "a", "text": "Type B devices have lower magnetic trip thresholds (3-5× In), meaning they require less fault current to trip instantaneously, thereby tolerating higher circuit impedance"}, {"id": "b", "text": "Type C devices are more sensitive and need higher Zs limits"}, {"id": "c", "text": "The Zs requirements only apply to Type B devices"}, {"id": "d", "text": "The difference is due to thermal overload characteristics only"}]', '["a"]', 'CORRECT — Type B MCBs trip magnetically at 3-5× In, Type C at 5-10× In, Type D at 10-20× In. Because the magnetic trip threshold differs, the same Zs produces different fault currents and thus different tripping times. A Type B device needs a lower Zs to ensure the fault current (Zs/table_max) produces sufficient magnetic force to trip within 0.4s for final circuits. Type C and D tolerate higher Zs because their higher thresholds still produce enough magnetic force at the same Zs. Option B is wrong — Type C doesn''t need higher Zs, it tolerates it. Option C is false. Option D is wrong — the difference is magnetic (instantaneous), not thermal.', 'AS/NZS 3000:2018 Table 5.1; AS/NZS 60898.1', 4, NULL, '2026-05-09 10:36:15.901698+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('5bb0b2ec-2923-587b-8975-e31b08277ce7', 'ba7ca948-df8c-56bc-92f8-38551ab0c928', 'According to AS/NZS 3000, which of the following tables must be correctly referenced to apply diversity factors and calculate the maximum demand for a single domestic electrical installation?', '[{"id": "a", "text": "Table 3.2"}, {"id": "b", "text": "Table 4.2"}, {"id": "c", "text": "Table 5.1"}, {"id": "d", "text": "Table 8.1"}]', '["a"]', 'CORRECT — Table 4.2 diversity factors apply to GROUPS of similar circuits. Individual dedicated circuits at their protective device rating are taken at 100% — no diversity is applied to a dedicated cooktop circuit or hot water circuit. The diversity is applied to groups: e.g., 8 identical lighting circuits: first 2 at 100%, remaining at 50%. Option B is wrong — dedicated circuits at their device rating don''t receive additional diversity. Option C is wrong — Table 4.2 applies to all installation types. Option D is wrong — diversity is applied after subdivision, to groups of similar loads.', 'AS/NZS 3000:2018 Table 4.2; Clause 4.2', 4, NULL, '2026-05-09 10:36:15.901698+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('3a1a6ba5-3c16-5ab8-8d5e-3775e88224a1', '08a18891-41e0-5ebe-86d4-86aecf47cf61', 'When performing a mandatory insulation resistance test on a standard 230V final subcircuit, what is the DC test voltage specified by AS/NZS 3000?', '[{"id": "a", "text": "500V DC"}, {"id": "b", "text": "250V DC"}, {"id": "c", "text": "1000V DC"}, {"id": "d", "text": "230V AC"}]', '["a"]', NULL, 'AS/NZS 3000 Table 8.1', 3, NULL, '2026-05-12 08:24:59.587524+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('fd62add0-905c-5430-9cf3-2fc98c73c689', '4a54f2ca-b514-539b-b086-a779d234b99f', 'What is the primary technical advantage of utilizing High Rupturing Capacity (HRC) fuses over standard Miniature Circuit Breakers (MCBs) in large industrial main switchboards?', '[{"id": "a", "text": "They possess a significantly higher short-circuit breaking capacity to safely clear massive fault currents without catastrophic failure"}, {"id": "b", "text": "They can be easily reset by the machine operator without requiring replacement components"}, {"id": "c", "text": "They provide highly sensitive residual earth leakage protection down to 10mA"}, {"id": "d", "text": "They automatically eliminate the need for an earth fault loop impedance return path"}]', '["a"]', NULL, 'AS/NZS 3000 Clause 2.6; AS/NZS IEC 60269', 4, NULL, '2026-05-12 08:24:59.587524+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('1b61e847-204c-5d8c-8528-74910edd9ec4', '4485a268-25ec-58de-8df8-5fa3df330063', 'In a Star connected electrical system, state the angle between line voltage and phase voltage.', '[{"id": "a", "text": "30° (Line voltage leads phase voltage by 30°)"}, {"id": "b", "text": "0° (Line and phase voltages are perfectly in phase)"}, {"id": "c", "text": "90° (Standard quadrature separation)"}, {"id": "d", "text": "180° (Complete phase inversion)"}]', '["a"]', 'CORRECT — In a star (wye) connected system, the line voltage (Vline) and phase voltage (Vphase) relationship is Vline = √3 × Vphase. This means Vphase = Vline/√3. The phase angle between them is 30° because the line voltage is the phasor difference between two phase voltages, not the magnitude of a single phase. Vectorially, Vline = Vphase × √3∠30°. This is fundamental three-phase theory.
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('4f73dcf2-8984-5326-84f8-65b69a611e2d', 'ba7ca948-df8c-56bc-92f8-38551ab0c928', 'Under AS/NZS 3000 maximum demand rules (domestic installations), how is the maximum demand calculated for the indoor lighting load?', '[{"id": "a", "text": "3A for the first 1 to 20 lighting points, plus 2A for each additional 20 points or part thereof"}, {"id": "b", "text": "Assessed at exactly 100% of the total connected lighting load to ensure maximum safety margin"}, {"id": "c", "text": "A flat 10A base load is applied to the entire installation regardless of the total number of lighting points"}, {"id": "d", "text": "5A for the first 10 points, plus 1A for each individual point thereafter"}]', '["a"]', NULL, 'AS/NZS 3000 Table 3.2 Load Group A', 3, NULL, '2026-05-12 08:24:59.587524+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('6e92d2ae-19ad-59ae-aef7-56777ca3eab1', '33c66c01-f417-510d-be43-101e18e33a5d', 'Under the New Zealand Electricity (Safety) Regulations 2010 and ECP 51, what specific Prescribed Electrical Work (PEW) is an owner-occupier of a domestic residence legally permitted to perform themselves, provided they live in the property?', '[{"id": "a", "text": "Removing and replacing existing switches, socket-outlets, and light fittings with identical matching types"}, {"id": "b", "text": "Installing a new main switchboard or upgrading the capacity of the consumer mains"}, {"id": "c", "text": "Performing general electrical maintenance on a property they own but strictly rent out to tenants"}, {"id": "d", "text": "Installing and commissioning a new grid-tied solar photovoltaic (PV) inverter system"}]', '["a"]', NULL, 'ECP 51; NZ Electricity (Safety) Regulations 2010', 2, NULL, '2026-05-12 08:24:59.587524+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('b57dfd37-2d2a-5780-8324-54ae3ad91bdd', '08a18891-41e0-5ebe-86d4-86aecf47cf61', 'When performing a mandatory insulation resistance test on a Separated Extra-Low Voltage (SELV) circuit, what test voltage and minimum resistance value are dictated by AS/NZS 3000?', '[{"id": "a", "text": "A 250V DC test voltage, yielding a minimum acceptable resistance of 0.5 M ohm"}, {"id": "b", "text": "A 500V DC test voltage, yielding a minimum acceptable resistance of 1.0 M ohm"}, {"id": "c", "text": "A 1000V DC test voltage, yielding a minimum acceptable resistance of 2.0 M ohm"}, {"id": "d", "text": "A 50V DC test voltage, yielding a minimum acceptable resistance of 0.1 M ohm"}]', '["a"]', NULL, 'AS/NZS 3000 Table 8.1', 3, NULL, '2026-05-12 08:24:59.587524+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('699ea78b-011a-5636-8031-bcfdd928c89a', '061d9060-cc7d-5338-a541-044dce012e11', 'The earth fault loop impedance (Zs) for a circuit is 0.85Ω. The external earth fault loop impedance (Ze) measured at the main switchboard is 0.35Ω. What is the impedance of the earth fault loop within the circuit itself (Zt)?', '[{"id": "a", "text": "0.50Ω"}, {"id": "b", "text": "0.35Ω"}, {"id": "c", "text": "1.20Ω"}, {"id": "d", "text": "0.85Ω"}]', '["a"]', 'CORRECT — The earth fault loop comprises two parts: the external loop (Ze, from the supply transformer to the main switchboard) and the internal loop (Zt, within the installation from the main switchboard to the fault point). The governing equation is: Zs = Ze + Zt. Rearranging: Zt = Zs − Ze = 0.85Ω − 0.35Ω = 0.50Ω.
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('ecc4c3ac-aace-549e-bb7d-b60e7a36cecb', '08a18891-41e0-5ebe-86d4-86aecf47cf61', 'What is the minimum acceptable insulation resistance value when testing a low voltage electrical installation with a 500V insulation tester?', '[{"id": "a", "text": "1 MΩ"}, {"id": "b", "text": "0.5 MΩ"}, {"id": "c", "text": "2 MΩ"}, {"id": "d", "text": "100 kΩ"}]', '["a"]', 'CORRECT — AS/NZS 3000 Clause 8.3.4 and Table 8.1 specify 1 MΩ as the minimum insulation resistance for any circuit or complete installation when tested with a 500V insulation tester. This 1 MΩ limit applies to all final circuits, sub-mains, and main circuits.
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('b3554721-01cb-5f82-89a0-f5bca02290dd', 'cf002c8c-36ac-50c7-a590-36ab31e09e40', 'Using the voltage drop calculation method in AS/NZS 3008, a cable with a Vc value of 10.5 mV/A.m is run 60 metres at 20 amps. The voltage drop (rounded) is:', '[{"id": "a", "text": "12.6V"}, {"id": "b", "text": "8.4V"}, {"id": "c", "text": "21V"}, {"id": "d", "text": "6.3V"}]', '["a"]', 'CORRECT — The k-factor voltage drop formula is V = k × I × L, where k is taken from AS/NZS 3000 Table 3 (installation method dependent), I is circuit current in amps, and L is length in kilometres. Converting 60m to 0.06km: V = 10.5 × 20 × 0.06 = 12.6V.
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('dd1bfb1a-6acb-5cec-9e49-3dc2c22d2cd4', '32b93254-79c6-5d4d-b9b1-ca2e1fa2a440', 'According to AS/NZS 3000, when determining the maximum demand for consumer mains or submains, which of the following must be established before applying diversity factors?', '[{"id": "a", "text": "The maximum demand calculated from the actual connected load"}, {"id": "b", "text": "The sum of all load nameplate ratings"}, {"id": "c", "text": "The supplier''s declared capacity at the point of supply"}, {"id": "d", "text": "The fault level at the main distribution board"}]', '["a"]', 'CORRECT — AS/NZS 3000 Clause 4.2 requires maximum demand to be calculated from the actual connected load. ''Connected load'' means the sum of all installed loads that could reasonably be expected to operate simultaneously — not the theoretical nameplate maximum. Diversity factors from Table 4.2 are then applied to this realistic connected load figure to arrive at the design maximum demand.
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('f7ef7d81-aa56-548d-a2b5-75ad05323127', 'cf002c8c-36ac-50c7-a590-36ab31e09e40', 'According to AS/NZS 3000, in a standard low-voltage installation (without an on-site substation), what is the maximum permissible voltage drop between the point of supply and any load, including sub-mains feeding mixed lighting and power loads?', '[{"id": "a", "text": "5% of the nominal voltage (11.5V for 230V)"}, {"id": "b", "text": "7% of the nominal voltage (16.1V for 230V)"}, {"id": "c", "text": "5% for lighting loads and 7% for power loads"}, {"id": "d", "text": "3% of the nominal voltage (6.9V for 230V)"}]', '["a"]', 'CORRECT — AS/NZS 3000 Clause 3.6.2 distinguishes: lighting circuits (5% limit) vs general circuits (7% limit). A sub-main that feeds both lighting and power is classified as a general-use circuit — 7% limit applies. The strictest limit in a mixed board is 5% (for the lighting portion) but the sub-main itself is assessed at 7% because it is not exclusively a lighting circuit. Option B applies only to dedicated lighting sub-mains. Option C is not a standard limit. Option D — sub-mains do not get a higher limit than final circuits.', 'AS/NZS 3000:2018 Clause 3.6.2', 3, NULL, '2026-05-09 10:36:15.901698+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('38e5213c-2f2f-5fe0-a226-b78214126a69', '4a54f2ca-b514-539b-b086-a779d234b99f', 'Which device provides combined protection against both overcurrent and earth fault on a final circuit?', '[{"id": "a", "text": "RCBO (Residual Current Breaker with Overload)"}, {"id": "b", "text": "RCD (Residual Current Device) only"}, {"id": "c", "text": "MCCB (Moulded Case Circuit Breaker)"}, {"id": "d", "text": "HRC fuse"}]', '["a"]', 'CORRECT — An RCBO (Residual Current Breaker with Overload) combines the overcurrent tripping function of an MCB/MCCB with the earth-leakage detection of an RCD in a single device. It provides comprehensive protection for final circuits: the MCB element trips on overcurrent (short circuit or overload), while the RCD element trips on earth leakage (typically 30mA for personal protection). AS/NZS 3000 Clause 2.6.2 mandates RCD or RCBO protection for socket outlets and other specified circuits.
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('f7846c55-a146-546d-887d-142870bd4e5f', '4485a268-25ec-58de-8df8-5fa3df330063', 'In a TN-C-S earthing system, the combined neutral and protective earth function is carried by the:', '[{"id": "a", "text": "PEN conductor, separated at the installation origin into separate N and PE conductors"}, {"id": "b", "text": "Pure earth electrode buried at the main switchboard"}, {"id": "c", "text": "IT system with impedance earthed neutral"}, {"id": "d", "text": "A dedicated earth rod at each distribution board"}]', '["a"]', 'CORRECT — TN-C-S (Protective Earth Neutral — Combined Separate) is the dominant supply system in New Zealand. The PEN conductor combines the neutral and earth functions from the transformer/substation and runs as a single conductor to the point of supply (the installation origin). At this point, the PEN is split into separate N (neutral) and PE (protective earth) conductors that remain separate throughout the installation. The MET (Main Earth Terminal) establishes the link between the consumer earth electrode and the PE busbar.
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('bf0bbca8-4ec1-5cfe-9b9b-e341ab5b86fe', 'cf002c8c-36ac-50c7-a590-36ab31e09e40', 'From the mains to a furthest socket outlet, the voltage drop contributions are: mains cable 4.2V, sub-main 4.5V, final circuit 3.8V. For a 230V lighting installation, this installation:', '[{"id": "a", "text": "Fails — total voltage drop of 12.5V exceeds the 11.5V limit"}, {"id": "b", "text": "Passes — total voltage drop of 12.5V is within the 5% limit"}, {"id": "c", "text": "Fails — the sub-main voltage drop must be recalculated at 7%"}, {"id": "d", "text": "Passes — only the final circuit is relevant to the lighting limit"}]', '["a"]', 'CORRECT — AS/NZS 3000 Clause 3.6.2 requires that total voltage drop from the point of supply to the furthest outlet shall not exceed the specified limit. For lighting: 5% × 230V = 11.5V. The combined drop is 3.2 + 4.1 + 3.8 = 11.1V. While 11.1V < 11.5V (technically a pass), the question flags this as a borderline scenario: measurement tolerances, supply voltage variation, and volt-drop formula approximations mean the result could swing above or below 11.5V in practice. A competent electrician would flag this and consider upsizing conductors.
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('7ea7ccd7-9e5e-56aa-9795-a7ced620d892', '72860a92-1d9b-550e-b0f8-648c5100c321', 'A switchboard circuit chart must show:', '[{"id": "a", "text": "The type and rating of each protective device and the circuit it supplies, kept up to date reflecting current configuration"}, {"id": "b", "text": "Only the main switch rating"}, {"id": "c", "text": "The owner''s name and contact details"}, {"id": "d", "text": "A schematic of the supply authority network"}]', '["a"]', 'CORRECT — AS/NZS 3000 Clause 2.8 and Electricity (Safety) Regulations require a circuit chart or legend identifying each circuit, its protective device type and rating, and what it supplies. The chart must be kept current — changes to the installation must be reflected in an updated chart. Option B is insufficient. Option C is not required by AS/NZS 3000. Option D is not required.', 'AS/NZS 3000:2018 Clause 2.8', 3, NULL, '2026-05-09 10:36:15.901698+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('0420eab5-44c5-5f14-8372-c50700c8b8f7', '08a18891-41e0-5ebe-86d4-86aecf47cf61', 'When testing the insulation resistance of a 400V three-phase motor circuit, which test voltage is appropriate according to AS/NZS 3000?', '[{"id": "a", "text": "500V DC insulation tester"}, {"id": "b", "text": "1000V DC insulation tester"}, {"id": "c", "text": "250V DC insulation tester"}, {"id": "d", "text": "A continuity tester on low voltage range"}]', '["a"]', 'CORRECT — AS/NZS 3000 Clause 8.3.6 requires insulation resistance testing at a voltage that is (a) not less than 500V DC, and (b) at least twice the nominal voltage of the circuit. For a 400V three-phase circuit the nominal voltage is 400V; twice that is 800V — but the minimum test voltage is 500V DC, and the next standard tester voltage above 500V is 500V DC itself (not 1000V, which is reserved for circuits operating above 500V nominal). A 400V motor circuit falls in the ''up to 500V'' category, so 500V DC is the correct tester. AS/NZS 3000 Table 8.1 and the IEC 60060-2 insulation tester standard both confirm this classification.
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('c55125fa-e0fe-5b65-ac77-2b6183b0dc7b', '32b93254-79c6-5d4d-b9b1-ca2e1fa2a440', 'Under the NZ Electricity (Safety) Regulations, which of the following is classified as notifiable work requiring notification to the EWRB before commencement?', '[{"id": "a", "text": "Installation of a new circuit for a cooking appliance"}, {"id": "b", "text": "Replacement of a damaged socket outlet"}, {"id": "c", "text": "Relocation of a light switch within the same room"}, {"id": "d", "text": "Replacement of a circuit breaker of the same rating"}]', '["a"]', 'CORRECT — The Electricity (Safety) Regulations 2010 (Schedule 2) specifies that adding a new circuit to an installation is notifiable work. Cooking appliances (cooktops, ovens) require dedicated circuits per AS/NZS 3000 Clause 4.2, so this represents a genuine circuit addition. Notification must be lodged with the EWRB before work begins — not after.
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('29107e66-c2f1-5dc1-967e-2fd4cfa61a63', '4485a268-25ec-58de-8df8-5fa3df330063', 'In a TT supply system, the earth electrode resistance at the consumer''s premises must be:', '[{"id": "a", "text": "Low enough to ensure fault current operates the protective device within the required time"}, {"id": "b", "text": "Equal to the supply authority''s earth electrode resistance"}, {"id": "c", "text": "Greater than 200Ω to limit touch voltage"}, {"id": "d", "text": "Of no consequence as the MEN link provides the earth path"}]', '["a"]', 'CORRECT — In a TT system, the consumer''s earth electrode (Ra) is entirely separate from the supply authority''s earth electrode. There is no metallic fault path back to the transformer like in a TN system. The fault return path relies entirely on the consumer''s earth electrode and the soil resistance. The electrode resistance must be sufficiently low that, combined with the fault loop path, sufficient fault current flows to operate the protective device (MCB or fuse) within the time specified in AS/NZS 3000 Clause 5.3. If Ra is too high, fault current will be too low and the protective device may never trip — presenting a dangerous shock hazard.
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('dd86a2dc-5c72-5d6a-a1f8-9367faf81179', '4a54f2ca-b514-539b-b086-a779d234b99f', 'For proper selectivity (discrimination) between a main circuit breaker (160A) and a sub-circuit breaker (32A), which statement is correct?', '[{"id": "a", "text": "The main breaker should have a rating at least 1.5 times the sub-breaker and a short-time delay characteristic"}, {"id": "b", "text": "The sub-breaker should trip first because it has the lower rating under fault conditions"}, {"id": "c", "text": "Both breakers will always trip simultaneously regardless of settings"}, {"id": "d", "text": "Discrimination is only required between RCDs, not between MCBs"}]', '["a"]', 'CORRECT — Selectivity (discrimination) ensures that only the protective device closest to the fault opens, leaving the rest of the installation energised. For MCCBs, proper discrimination requires: (1) main device rating at least 1.5–2× the sub-device rating (160A main vs 32A sub = 5× ratio, well above minimum), AND (2) the main device must have a short-time delay (time delay) setting that allows the downstream device to complete its tripping operation before the upstream device begins to open. The 160A/32A ratio here far exceeds the 1.5× minimum, making discrimination readily achievable.
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('81271202-8df8-52f4-adc6-e4e0201cb38c', 'ac388207-779c-5a46-a6e9-b556f0578f56', 'When selecting a cable size for a 230V single-phase circuit, which AS/NZS 3000 requirement must be satisfied first?', '[{"id": "a", "text": "Current-carrying capacity (ampacity) must be determined from AS/NZS 3008"}, {"id": "b", "text": "Voltage drop must be checked and within limits before ampacity is considered"}, {"id": "c", "text": "The cheapest cable that fits the conduit must always be used"}, {"id": "d", "text": "Earth conductor size can be half the active conductor size for circuits under 50m"}]', '["a"]', 'CORRECT — AS/NZS 3000 Clause 3.2 requires that conductor size be determined with primary regard to current-carrying capacity, which must be established from AS/NZS 3008 Tables. These tables account for installation method, ambient temperature, grouping, conduit size, and other thermal factors to establish the maximum current the cable can carry safely without overheating. This is the first step — the voltage drop check then runs in parallel as a separate requirement.
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('61d50ae9-c155-577c-af92-5494fc8ff67e', 'cd6d17a6-eac4-54af-a1b2-c443e9b8523b', 'In what sequence should insulation resistance testing be carried out on a new installation according to AS/NZS 3000?', '[{"id": "a", "text": "All circuits isolated from the supply, with tests conducted between active/neutral conductors and all live parts to earth"}, {"id": "b", "text": "All circuits energised, with tests conducted between live conductors and earth with circuits connected"}, {"id": "c", "text": "Only the main switchboard needs testing before circuit testing"}, {"id": "d", "text": "Before the earth continuity test is performed"}]', '["a"]', 'CORRECT — AS/NZS 3000 Clause 8.3.6.1 explicitly requires that insulation resistance testing be carried out with the installation isolated from the supply. The circuit must be de-energised, all main switches OFF, and the installation physically disconnected from the grid before applying the 500V DC test voltage. Within the isolated installation, switches (including lighting switches) are placed in the ON position so that the test voltage can travel through the entire length of each conductor. Tests are conducted between each live conductor and earth, and between adjacent live conductors (L-N). Critically, electronic equipment that may be damaged by 500V DC (such as RCDs, surge protection devices, or electronic dimmers) must be disconnected or bypassed before testing per Clause 8.3.6.2, or the test voltage reduced to 250V DC.
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('6854d619-351c-53b0-a7d3-98263a4817d3', '647fd115-7e2c-5505-9d7c-bc0583d79045', 'In a Direct On Line (DOL) motor starter, the overload relay is sized as a percentage of full load current (FLC). The correct setting is typically:', '[{"id": "a", "text": "100–112% of the motor nameplate FLC"}, {"id": "b", "text": "80% of the motor nameplate FLC"}, {"id": "c", "text": "150% of the motor nameplate FLC for short-time operation"}, {"id": "d", "text": "Equal to the starting current of the motor"}]', '["a"]', 'CORRECT — Thermal overload relays in DOL starters are set to 100–112% of the motor nameplate FLC. This allows the motor to operate continuously at its rated current without nuisance tripping, while still protecting against sustained overloads that would cause winding overheating. AS/NZS IEC 60947-4-1 governs the overload relay requirements.
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('32bd5914-1f1d-553b-aa6f-d3f24e5c5138', '4b09cc13-dedd-58f5-880c-9d460f74562e', 'In AC circuit theory, if a circuit is purely capacitive (containing zero resistance and zero inductance), what is the specific phase relationship between the alternating current and the applied voltage?', '[{"id": "a", "text": "The current leads the voltage by exactly 90 degrees"}, {"id": "b", "text": "The current lags the voltage by exactly 90 degrees"}, {"id": "c", "text": "The current and voltage are perfectly in phase at 0 degrees"}, {"id": "d", "text": "The current leads the voltage by exactly 45 degrees"}]', '["a"]', NULL, 'Basic AC theory — capacitive reactance', 2, NULL, '2026-05-12 08:24:59.587524+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('29dda122-3eec-54a5-b137-90e8752093ee', '32b93254-79c6-5d4d-b9b1-ca2e1fa2a440', 'Under AS/NZS 3000:2018, in non-domestic and non-residential installations, 30mA RCD protection is mandatory for final sub-circuits supplying socket outlets rated up to and including:', '[{"id": "a", "text": "32A — all socket outlets up to and including 32A must be RCD protected"}, {"id": "b", "text": "20A — all socket outlets up to and including 20A must be RCD protected"}, {"id": "c", "text": "15A — the standard socket outlet is the threshold"}, {"id": "d", "text": "10A — only 10A outlets are covered"}]', '["a"]', 'CORRECT — AS/NZS 3000 Clause 2.6.2 requires that all socket outlets with a rating not exceeding 20A shall be RCD-protected. This covers standard 10A, 15A, and 20A socket outlets — virtually every socket outlet in domestic and commercial premises. The 20A threshold captures all standard socket outlets used for portable equipment that may be handled during a fault. This is a core safety provision because portable equipment is the highest-risk category for earth faults involving human contact.
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('790da0e3-5603-5b3e-a1b5-b168bf206b54', '72860a92-1d9b-550e-b0f8-648c5100c321', 'Under AS/NZS 3000, a main switch on a switchboard must be:', '[{"id": "a", "text": "Capable of being operated by one person and clearly labelled as the main switch for each installation or separately switched section"}, {"id": "b", "text": "A 3-phase circuit breaker rated at the incomer capacity"}, {"id": "c", "text": "Installed inside the premises for security reasons"}, {"id": "d", "text": "Protected by an RCD to prevent shock during operation"}]', '["a"]', 'CORRECT — AS/NZS 3000 Clause 2.8 and the Electricity (Safety) Regulations require that a switchboard shall have a main switch (or switches) clearly labelled to identify what they control, and capable of being operated by one person. The switch must isolate the entire installation (or the relevant separately switched section). Switchboards must be accessible — not concealed inside cupboards, enclosed spaces, or behind barriers.
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('c1285a4e-681b-5e9b-a916-f172677dbd6d', 'cf002c8c-36ac-50c7-a590-36ab31e09e40', 'A 0.8km final sub-circuit carries 15A. The cable has a Vc value of 11.7 mV/A.m. Using the standard formula Vd = (L × I × Vc) / 1000, the calculated voltage drop is:', '[{"id": "a", "text": "140.4V"}, {"id": "b", "text": "14.04V"}, {"id": "c", "text": "1404V"}, {"id": "d", "text": "70.2V"}]', '["a"]', 'CORRECT — V = k × I × L = 11.7 × 15 × 0.8 = 140.4 ÷ 10 (100m unit) = 14.04V. For a 230V general circuit, 14.04V is within the 7% limit (16.1V). Option B (7.02V) would result from using 0.4km. Option C (28.08V) requires a 2km run. Option D (3.51V) is dividing by 40 instead of 10 in the unit conversion.', 'AS/NZS 3000:2018 Clause 3.6; Table 3', 3, NULL, '2026-05-09 10:36:15.901698+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('ab92c646-1a6c-5d26-9d6d-d81f5a33d23f', 'cf002c8c-36ac-50c7-a590-36ab31e09e40', 'A single-phase circuit is 40m long and carries a load of 20A. The maximum allowable voltage drop is 11.5V. Based on the following AS/NZS 3008 Vc values, what is the minimum compliant cable size required to stay within the voltage drop limit?', '[{"id": "a", "text": "4mm² (Vc = 9.71 mV/A.m)"}, {"id": "b", "text": "2.5mm² (Vc = 15.6 mV/A.m)"}, {"id": "c", "text": "6mm² (Vc = 6.49 mV/A.m)"}, {"id": "d", "text": "1.5mm² (Vc = 28.1 mV/A.m)"}]', '["a"]', 'CORRECT — At 40m with 20A load, 4mm² drops 6.2V. To achieve ≤9.2V, the current-carrying capacity must be checked and if the existing conductor passes ampacity but fails volt-drop, the next standard size up (6mm²) must be selected. AS/NZS 3000 Clauses 3.2 and 3.6 require both ampacity AND voltage drop to be satisfied — where volt-drop governs, the larger conductor is mandatory. Option B fails because the question explicitly asks what is needed to meet the 9.2V limit. Option D (2.5mm²) would be worse.', 'AS/NZS 3000:2018 Clauses 3.2, 3.6; AS/NZS 3008', 4, NULL, '2026-05-09 10:36:15.901698+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('92f7aa6a-ebf1-5c7b-8bc9-0e87148bbaaf', 'cf002c8c-36ac-50c7-a590-36ab31e09e40', 'Three identical 230V single-phase sub-circuits share a common conduit. Each carries 10A. When calculating voltage drop for the worst-case circuit, the correct approach is:', '[{"id": "a", "text": "Calculated individually using only that specific circuit''s current and length, without derating factors applied to the voltage drop calculation"}, {"id": "b", "text": "Calculated using the combined current of all three circuits divided by three"}, {"id": "c", "text": "Calculated individually, then multiplied by a grouping diversity factor of 0.7"}, {"id": "d", "text": "Calculated using the sum of lengths for all circuits in the conduit"}]', '["a"]', 'CORRECT — AS/NZS 3008 voltage drop calculations are per-circuit, per-current, per-length. The grouping factor for current-carrying capacity (AS/NZS 3008 Table 2) does NOT change the individual circuit voltage drop calculation. Each circuit''s voltage drop is calculated using its own current and resistance — the fact that cables are in the same conduit is already implicitly accounted for in the k-factor. Option B — grouping affects ampacity (heating), not voltage drop. Option C — this is incorrect. Option D — no such voltage drop grouping factor exists in AS/NZS 3000.', 'AS/NZS 3000:2018 Clause 3.6; AS/NZS 3008 Tables 1-30', 3, NULL, '2026-05-09 10:36:15.901698+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('e8ddfdad-db01-5d2f-947b-2dcd5abd625f', 'cf002c8c-36ac-50c7-a590-36ab31e09e40', 'A 400V three-phase circuit is 100m long, carrying 26A per phase. The cable Vc value is 1.8 mV/A.m. Using the formula V = √3 × Vc × I × L / 1000, what is the approximate voltage drop?', '[{"id": "a", "text": "8.1V"}, {"id": "b", "text": "4.7V"}, {"id": "c", "text": "14.0V"}, {"id": "d", "text": "16.2V"}]', '["a"]', 'CORRECT — V = √3 × k × I × L / 1000 = 1.732 × 1.8 × 26 × 100 / 1000 = 1.732 × 1.8 × 2.6 = 1.732 × 4.68 = 8.10V. This is within the 7% voltage drop limit for a general motor circuit (400V × 0.07 = 28V). Option B (4.7V) would be using 0.5km instead of 0.1km. Option C (14V) would require k=3.1 which is for a different installation method.', 'AS/NZS 3000:2018 Clause 3.6; AS/NZS 3008', 3, NULL, '2026-05-09 10:36:15.901698+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('bad21066-ed1d-5763-a346-31fd0d11756b', 'cf002c8c-36ac-50c7-a590-36ab31e09e40', 'When voltage drop calculations require a larger conductor than current-carrying capacity calculations, the installation designer must:', '[{"id": "a", "text": "Select the larger conductor size determined by voltage drop — both requirements must be satisfied"}, {"id": "b", "text": "Always use the ampacity-derived size and document the voltage drop deviation"}, {"id": "c", "text": "Apply to the supply authority for a voltage variation approval"}, {"id": "d", "text": "Use voltage-drop size only for lighting, ampacity size for power circuits"}]', '["a"]', 'CORRECT — AS/NZS 3000 Clause 3.2 is explicit: conductor size must satisfy BOTH current-carrying capacity AND voltage drop requirements. Where voltage drop requires a larger conductor, the larger size is mandatory. This is not optional and does not require supply authority approval for normal installations — the designer simply selects the larger conductor. Option B is non-compliant — voltage drop is a mandatory requirement. Option C is only applicable in exceptional circumstances where supply authority voltage variation is agreed. Option D is arbitrary and not supported by the standard.', 'AS/NZS 3000:2018 Clauses 3.2, 3.6', 4, NULL, '2026-05-09 10:36:15.901698+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('d25c7026-35f3-550a-aa61-18b72d69dafa', 'cf002c8c-36ac-50c7-a590-36ab31e09e40', 'Voltage drop in a conductor is proportional to which combination of factors?', '[{"id": "a", "text": "Current flowing and conductor resistance (which increases with length and decreases with larger cross-section)"}, {"id": "b", "text": "Supply voltage and frequency"}, {"id": "c", "text": "Ambient temperature and installation method only"}, {"id": "d", "text": "Power factor and reactive impedance only"}]', '["a"]', 'CORRECT — Ohm''s Law for a conductor: V = I × R. Resistance R = ρ × L / A. So V_drop increases with higher current and longer length, and decreases with larger conductor area. Option B — supply voltage determines the percentage limit context, not the magnitude of V_drop in the formula. Frequency has no effect on resistive volt-drop in this context. Option C — ambient temperature affects ampacity but not directly the volt-drop formula (though temperature slightly increases R). Option D — for purely resistive circuits at 50Hz, PF has no effect; for circuits with significant reactance, PF affects reactive volt-drop component, but AS/NZS 3000''s simplified volt-drop method using k-factors accounts for this.', 'AS/NZS 3000:2018 Clause 3.6', 3, NULL, '2026-05-09 10:36:15.901698+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('01e0bd4a-f371-5352-b5ec-df9301011bb0', '061d9060-cc7d-5338-a541-044dce012e11', 'Which of the following describes the correct procedure for measuring the total earth fault loop impedance (Zs) at a final sub-circuit socket outlet?', '[{"id": "a", "text": "The measurement is taken between the active and earth pins with the circuit fully energised"}, {"id": "b", "text": "The measurement is taken between the active and neutral pins with the installation completely isolated"}, {"id": "c", "text": "The measurement is taken between the earth pin and the main earth electrode with the circuit isolated"}, {"id": "d", "text": "The measurement is taken between the active and earth pins with the protective earth conductor intentionally disconnected"}]', '["a"]', 'CORRECT — Zs is measured with the installation energised and earthing fully connected. The instrument measures between line and earth at the outlet — this gives Zs = Ze + Zt (total loop). AS/NZS 3019 specifies the method: a high-current test pulse (15-20A) is injected between line and earth and the resulting voltage drop is measured. Option B is wrong — disconnecting earthing breaks the loop, giving an open-circuit reading, not Zs. Option C gives the neutral-earth voltage which indicates neutral integrity issues, not loop impedance. Option D is false — Zs is routinely measured in-service with a loop impedance tester.', 'AS/NZS 3019; AS/NZS 3000 Clause 5.3', 3, NULL, '2026-05-09 10:36:15.901698+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('eed3d18f-4168-54d0-9c23-5f3abeef404d', '061d9060-cc7d-5338-a541-044dce012e11', 'Ze (external earth fault loop impedance) is primarily the responsibility of:', '[{"id": "a", "text": "The supply network operator — it is measured at the point of supply and is outside the electrician''s scope"}, {"id": "b", "text": "The installing electrician who designed the installation"}, {"id": "c", "text": "The property owner"}, {"id": "d", "text": "The meter service provider"}]', '["a"]', 'CORRECT — Ze is the external loop impedance from the supply transformer to the point of supply. The supply authority is responsible for maintaining Ze at a level that allows the installation''s protective devices to operate within AS/NZS 3000 Table 5.1 limits when combined with the installation''s internal Zt. The electrician''s responsibility is Zt (internal loop impedance within the installation). Ze is declared by the supply authority and can be measured at the point of supply. Option B — electrician is responsible for Zt, not Ze. Option C — property owners have no responsibility for supply network characteristics. Option D — meter providers deal with metering, not supply earthing.', 'AS/NZS 3000:2018 Clause 5.2; NZ Electrical Regulations', 3, NULL, '2026-05-09 10:36:15.901698+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('eb76e9ba-cc2e-502f-89c2-2e0843e335e5', '061d9060-cc7d-5338-a541-044dce012e11', 'The resistance of 50m of 2.5mm² copper phase conductor at 20°C is 0.694Ω. The earth continuity conductor in the same run is 1.5mm² with resistance 1.15Ω. The Zt contribution from this cable run is:', '[{"id": "a", "text": "1.84Ω (phase 0.694Ω + earth 1.15Ω, summed for the line-to-earth fault path)"}, {"id": "b", "text": "0.694Ω only — the earth path resistance is not included in Zt for a line-to-earth fault"}, {"id": "c", "text": "2.31Ω (direct sum of phase and earth resistance)"}, {"id": "d", "text": "Zt cannot be calculated without knowing the actual route length of the earth conductor"}]', '["a"]', 'CORRECT — For a line-to-earth fault, the fault current path is: line conductor (origin → fault) + earth continuity conductor (fault → origin MET). The total loop resistance is Rline + Rearth. 50m of 2.5mm² copper = 0.694Ω (phase). 50m of 1.5mm² copper = 1.15Ω (earth CPC). Zt = 0.694 + 1.15 = 1.844Ω. Option B is wrong — Zt includes the earth return path. Option C is wrong — while the correct answer is numerically close to this, the correct concept is that both path segments must be summed. Option D is wrong — the route length of the earth is the same as the phase for a single cable run.', 'AS/NZS 3000:2018 Clause 5.2; AS/NZS 3008', 4, NULL, '2026-05-09 10:36:15.901698+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('e1ea21f1-33da-56e9-8174-5ad8e2a27fd2', '061d9060-cc7d-5338-a541-044dce012e11', 'Prospective fault current (PFC) at a main switchboard is measured at 3.2kA. The main switch is rated at 5kA. This installation:', '[{"id": "a", "text": "Is acceptable — the switch rating exceeds the maximum available fault current with adequate margin"}, {"id": "b", "text": "Fails — the PFC exceeds the switch rating"}, {"id": "c", "text": "Is borderline — a 40% derating factor must be applied"}, {"id": "d", "text": "Is only acceptable if the PFC decreases below 2.5kA"}]', '["a"]', 'CORRECT — Protective devices must have an interrupting capacity (Icu/Icn) not less than the prospective fault current at the point of installation. A 5kA-rated device at a location where PFC = 3.2kA provides a 1.56× margin — well above the minimum requirements. Option B is wrong because 3.2kA < 5kA. Option C is wrong — no 40% derating is required when the device rating exceeds PFC. Option D is wrong — there is no such rule.', 'AS/NZS 3000:2018 Clause 2.6; AS/NZS 60898.1', 3, NULL, '2026-05-09 10:36:15.901698+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('bba167fe-9383-552e-8c31-b85ab015e6a4', '32b93254-79c6-5d4d-b9b1-ca2e1fa2a440', 'AS/NZS 3000 applies to electrical installations operating at which maximum voltage?', '[{"id": "a", "text": "1000V AC or 1500V DC (low voltage) — covering domestic through to light industrial"}, {"id": "b", "text": "Any voltage above extra-low voltage (ELV)"}, {"id": "c", "text": "33,000V — the limit for distribution networks"}, {"id": "d", "text": "230V/400V only"}]', '["a"]', 'CORRECT — AS/NZS 3000 applies to low voltage, defined as not exceeding 1000V AC or 1500V DC between conductors, or 600V AC or 900V DC between a conductor and earth. This covers 230V single-phase domestic through 400V three-phase commercial/industrial. Option B — ELV is up to 50V AC or 120V DC; AS/NZS 3000 covers low voltage, not ELV. Option C — 33kV is distribution voltage, above low voltage. Option D is false — the standard explicitly covers up to 1000V AC.', 'AS/NZS 3000:2018 Clause 1.4', 3, NULL, '2026-05-09 10:36:15.901698+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('c081d030-ccce-5189-b1ed-8e215099c907', '32b93254-79c6-5d4d-b9b1-ca2e1fa2a440', 'Per current NZ standards (AS/NZS 3000:2018 harmonised colour system), the colour coding for a neutral conductor in fixed wiring is:', '[{"id": "a", "text": "Blue (light blue) — harmonised international standard adopted in AS/NZS 3000:2018 for new work"}, {"id": "b", "text": "Black — the old NZ convention (pre-2018)"}, {"id": "c", "text": "Red — always the active/live conductor colour"}, {"id": "d", "text": "Green/Yellow — for neutral in fixed wiring"}]', '["a"]', 'CORRECT — AS/NZS 3000:2018 adopted the international harmonised colour scheme (IEC 60446): Brown = line, Blue = neutral, Green/Yellow = earth for new work. For existing installations (pre-2018) using the old NZ colours, Black = neutral and Red = active were used. The current standard applies Blue for neutral in fixed wiring. Option B is the old NZ convention. Option C is the old NZ active colour. Option D — Green/Yellow is always earth/protective conductor, never neutral.', 'AS/NZS 3000:2018 Clause 3.8; Table 3', 3, NULL, '2026-05-09 10:36:15.901698+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('24aa2809-66d0-55fa-a255-fc8c28879d07', '32b93254-79c6-5d4d-b9b1-ca2e1fa2a440', 'AS/NZS 3000 and NZ Electricity (Safety) Regulations require which documentation for a completed electrical installation?', '[{"id": "a", "text": "Certificate of Compliance (CoC) and Electrical Safety Certificate (ESC)"}, {"id": "b", "text": "A visual inspection checklist signed by the property owner"}, {"id": "c", "text": "The manufacturer’s warranty documentation for all installed switchgear"}, {"id": "d", "text": "A 10-year load forecast and thermal imaging report"}]', '["a"]', 'CORRECT — The Electricity (Safety) Regulations 2010 (NZ) and AS/NZS 3000 require a Certificate of Compliance (CoC) or Electrical Works Certificate to be issued by the licensed electrical worker for all notifiable work. Circuit schedules (legends/charts identifying each circuit and protective device) are also required where circuits have been installed or altered. Option B is insufficient. Option C is a product warranty matter, not a compliance requirement. Option D is a design document, not a regulatory requirement.', 'AS/NZS 3000:2018 Clause 1.6; Electricity (Safety) Regulations 2010 (NZ)', 3, NULL, '2026-05-09 10:36:15.901698+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('f808d71a-ed46-5064-8746-638704ee1443', '32b93254-79c6-5d4d-b9b1-ca2e1fa2a440', 'A Multiple Earthed Neutral (MEN) link is required in which type of earthing system in NZ?', '[{"id": "a", "text": "TN-C-S — where the supply PEN conductor is split at the installation origin into separate N and PE conductors connected by the MEN link"}, {"id": "b", "text": "TT system only — where the installation earth electrode is completely isolated from the supply"}, {"id": "c", "text": "IT system — high impedance earthed neutral"}, {"id": "d", "text": "DC systems only"}]', '["a"]', 'CORRECT — MEN is the NZ term for TN-C-S. The supply provides a PEN (combined neutral-earth) conductor from the transformer. At the installation''s origin, the PEN is ''split'' into N and PE, which are connected at the Main Earth Terminal via the MEN link. This is the standard NZ earthing arrangement per AS/NZS 3000 Clause 5.2.1. Option B — TT has no PEN conductor; each electrode is independent. NZ distribution networks are not TT. Option C — IT is used in hospitals/critical infrastructure, not standard NZ installations. Option D — MEN is an AC system requirement.', 'AS/NZS 3000:2018 Clause 5.2.1', 4, NULL, '2026-05-09 10:36:15.901698+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('c16aeae2-fd2f-51fe-afba-6477dc71ff6c', '4a54f2ca-b514-539b-b086-a779d234b99f', 'Under AS/NZS 3000:2018, what is the regulatory requirement for Residual Current Device (RCD) protection on domestic lighting circuits?', '[{"id": "a", "text": "All final subcircuits supplying lighting in a domestic installation must be protected by a 30mA RCD"}, {"id": "b", "text": "Only lighting circuits located within damp situations (e.g., bathrooms) require RCD protection"}, {"id": "c", "text": "Lighting circuits do not require RCD protection provided they are wired in double-insulated TPS cable"}, {"id": "d", "text": "RCD protection is only required if the lighting circuit protective device rating exceeds 10A"}]', '["a"]', NULL, 'AS/NZS 3000:2018 Clause 2.4', 3, NULL, '2026-05-12 08:24:59.587524+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('4ad7d5a3-4c0c-5384-8ee4-08a3785fd3fd', '32b93254-79c6-5d4d-b9b1-ca2e1fa2a440', 'Under the New Zealand Electricity Act 1992 Section 79 (Owner-Occupier Exemption) and ECP 51, which of the following statements correctly defines the limits of an unlicensed homeowner performing electrical work on their own domestic installation?', '[{"id": "a", "text": "They may install, extend, or alter a final subcircuit, provided the work is inspected, tested, and certified by a registered electrical inspector before connection to the supply"}, {"id": "b", "text": "They may carry out any notifiable electrical work, including replacing the main switchboard, provided they live in the property"}, {"id": "c", "text": "They are permitted to perform all electrical work without independent inspection, provided the property is not a rental"}, {"id": "d", "text": "They may install new consumer mains cables directly connecting the installation to the utility network"}]', '["a"]', 'CORRECT — The Electricity (Safety) Regulations 2010 (NZ) apply to all persons regardless of licence status. Notifiable work requires EWRB notification BEFORE commencement — this applies to ALL notifiable work, whether done by a property owner or licensed electrician. A licensed property owner CAN do notifiable work on their own property — but must still notify EWRB first. Option B is wrong — licence does not permit unrestricted work on any property. Option C is partially true (non-notifiable = no restriction; notifiable = licensed electrician required), but a licensed property owner IS a licensed electrician in this context. Option D — notification must be BEFORE work, not after.', 'Electricity (Safety) Regulations 2010 (NZ); EWRB guidelines', 3, NULL, '2026-05-09 10:36:15.901698+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('456cfcec-a966-57d0-b7a4-2b0e5b67c2a5', '32b93254-79c6-5d4d-b9b1-ca2e1fa2a440', 'Before connecting an electrical installation to the supply network, which must be completed?', '[{"id": "a", "text": "All tests in AS/NZS 3000 Chapter 8 (insulation resistance, earth continuity, Zs, polarity, RCD operation) and a Certificate of Compliance issued"}, {"id": "b", "text": "Visual inspection only — testing can be done after connection"}, {"id": "c", "text": "Testing only of circuits above 32A rating"}, {"id": "d", "text": "Only the main switch needs testing before energisation"}]', '["a"]', 'CORRECT — AS/NZS 3000 Clause 8.1 and the Electricity (Safety) Regulations require ALL verification tests to be completed BEFORE connection to the supply. These include: insulation resistance (all circuits and complete installation), earth continuity of protective conductors, Zs at the furthest point of each circuit, polarity, RCD operation, and any other specified tests. A Certificate of Compliance must also be issued. Option B is dangerous and non-compliant. Option C — all circuits must be tested regardless of rating. Option D is inadequate — comprehensive testing of all circuits is required.', 'AS/NZS 3000:2018 Clause 8.1; Appendix C', 3, NULL, '2026-05-09 10:36:15.901698+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('f899993b-4131-5b00-940c-88b1d0e2e196', '08a18891-41e0-5ebe-86d4-86aecf47cf61', 'When testing insulation resistance on a circuit containing electronic equipment (dimmers, electronic ballasts, VSDs), the correct approach is:', '[{"id": "a", "text": "Isolate or disconnect the electronic equipment before applying the 500V test voltage — it may be damaged or give false low readings"}, {"id": "b", "text": "Test through the electronic equipment as it is part of the installation"}, {"id": "c", "text": "Electronic equipment does not affect insulation resistance readings"}, {"id": "d", "text": "Apply only 250V test voltage to all circuits regardless of voltage rating"}]', '["a"]', 'CORRECT — Electronic equipment contains semiconductors and capacitors that can be damaged by the 500V DC insulation test voltage, and capacitors can store charge giving false low readings. AS/NZS 3000 Appendix C notes that electronic equipment should be disconnected or isolated before IR testing. Where disconnection is impractical, equipment should be tested separately per manufacturer instructions. Option B — applying insulation test voltage across electronic equipment can destroy it. Option C is false. Option D — the test voltage requirement does not change; the equipment must be isolated.', 'AS/NZS 3000:2018 Appendix C; equipment manufacturer instructions', 4, NULL, '2026-05-09 10:36:15.901698+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('53787614-52de-5c2d-a777-745b76c576fd', '08a18891-41e0-5ebe-86d4-86aecf47cf61', 'Insulation resistance readings taken in high humidity (above 80% RH) should be interpreted with caution because:', '[{"id": "a", "text": "Moisture creates leakage paths on insulation surfaces, giving artificially low readings that may improve significantly when dry"}, {"id": "b", "text": "High humidity has no effect on insulation resistance"}, {"id": "c", "text": "Humidity only affects readings above 500 MΩ"}, {"id": "d", "text": "IR testers automatically temperature- and humidity-compensate"}]', '["a"]', 'CORRECT — Moisture on conductor insulation, in terminations, and inside equipment creates conductive leakage paths that artificially reduce measured insulation resistance. A reading of 2 MΩ on a humid day could read 20 MΩ+ when dry. AS/NZS 3000 does not specify minimum humidity for testing but industry guidance is to note conditions and interpret borderline results in context. Condensation inside enclosures can cause genuine faults. Option B is false. Option C is nonsense. Option D is false — IR testers do not automatically compensate.', 'AS/NZS 3000:2018 Appendix C', 3, NULL, '2026-05-09 10:36:15.901698+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('3e726c2d-312b-5e15-81e0-0c3df09a2aa2', '647fd115-7e2c-5505-9d7c-bc0583d79045', 'In a star-delta motor starter, during the starting (star) configuration, the motor winding voltage is:', '[{"id": "a", "text": "V/√3 (≈58%) of line voltage, reducing starting torque to approximately 33% of DOL torque"}, {"id": "b", "text": "Equal to line voltage — star configuration has no voltage reduction effect"}, {"id": "c", "text": "V/2 — half the line voltage"}, {"id": "d", "text": "The same as delta but current is halved only"}]', '["a"]', 'CORRECT — In star, each winding is connected between a line and the star point. Winding voltage = Vline/√3 ≈ 0.577V. Since torque ∝ V², torque in star = (V/√3)² = V²/3 ≈ 33% of DOL torque. Starting current also reduces to 1/√3 ≈ 33% of DOL current. When near-rated speed, the starter switches to delta, applying full line voltage. Option B is false. Option C — V/2 is not the star winding voltage. Option D is wrong because winding voltage IS reduced in star.', 'AS/NZS IEC 60947-4-1; motor starting theory', 4, NULL, '2026-05-09 10:36:15.901698+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('7fd06e96-800e-5f80-a2fb-1e131d706053', '08a18891-41e0-5ebe-86d4-86aecf47cf61', 'A 230V lighting circuit and a 24V ELV circuit share the same conduit. The insulation resistance test on the 230V circuit should be conducted at:', '[{"id": "a", "text": "500V DC — the highest voltage circuit in the group determines the test voltage; the ELV circuit should be isolated first"}, {"id": "b", "text": "24V — to avoid damaging the ELV circuit"}, {"id": "c", "text": "250V DC — the average of the two voltages"}, {"id": "d", "text": "Test voltage selection is not relevant for mixed-voltage conduit runs"}]', '["a"]', 'CORRECT — AS/NZS 3000 Table 8.1 requires the test voltage to be appropriate to the circuit''s nominal voltage. For circuits operating above 50V and up to 500V, 500V DC is required. The ELV circuit in the same conduit must be isolated before testing the 230V circuit — the 500V test voltage could damage ELV equipment. Option B would give meaningless results for the 230V circuit. Option C has no basis in the standard. Option D is false — test voltage selection is critical and mandatory.', 'AS/NZS 3000:2018 Table 8.1; Clause 8.3.4', 3, NULL, '2026-05-09 10:36:15.901698+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('53f3bb55-9059-55c2-896b-2281b409c94c', 'ba7ca948-df8c-56bc-92f8-38551ab0c928', 'For maximum demand calculation, a 7.5kW three-phase motor with FLC of 20A should be assessed at:', '[{"id": "a", "text": "20A at 100% — motor circuits are assessed at full load current for MD; starting current is a transient not used in MD calculations"}, {"id": "b", "text": "20A × 125% = 25A to account for DOL starting"}, {"id": "c", "text": "20A × 80% = 16A using a commercial diversity factor"}, {"id": "d", "text": "Motor loads are excluded from MD calculations"}]', '["a"]', 'CORRECT — Motor circuits are assessed at 100% of full load current for maximum demand. Starting current (5-7× FLA for DOL) is a brief transient and is not used in MD calculations — MD is concerned with sustained loads. The motor overload relay is set at 100-112% of FLA per AS/NZS IEC 60947-4-1. Option B — starting current is not used in MD. Option C — no such 80% factor exists for motors. Option D — motors are significant sustained loads and must be included.', 'AS/NZS 3000:2018 Clause 4.2; AS/NZS IEC 60947-4-1', 4, NULL, '2026-05-09 10:36:15.901698+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('394a0d1d-4660-54f2-96c4-7978a909c4e3', '4a54f2ca-b514-539b-b086-a779d234b99f', 'A main 300mA Type S RCD at the main switchboard and a 30mA RCD at a distribution board installed in series achieves:', '[{"id": "a", "text": "Back-up protection — the 300mA RCD provides discrimination and fire protection while 30mA RCD provides personal protection at circuit level"}, {"id": "b", "text": "Full discrimination so only the downstream RCD ever trips"}, {"id": "c", "text": "An incorrect arrangement causing both to trip simultaneously on any fault"}, {"id": "d", "text": "300mA and 30mA RCDs cannot be installed in series"}]', '["a"]', 'CORRECT — A 300mA Type S (time-delayed) RCD at the origin provides discrimination against nuisance tripping of downstream 30mA RCDs, and fire protection (300mA can detect significant earth leakage that could cause heating/fire but is not sensitive enough for personal protection). The 30mA RCD at the distribution board provides personal protection for downstream circuits. This cascade arrangement is specifically recognised in AS/NZS 3000 Clause 2.6.2. Option B is wrong — the 300mA main will trip on high earth leakage faults. Option C is wrong — this is a correct, standard arrangement. Option D is false — series RCDs are common and correct.', 'AS/NZS 3000:2018 Clause 2.6.2; AS/NZS 61009.1', 4, NULL, '2026-05-09 10:36:15.901698+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('709f29ca-cdd6-5d6a-939d-afd69e5589da', '4a54f2ca-b514-539b-b086-a779d234b99f', 'Type C MCBs are specifically recommended for circuits supplying:', '[{"id": "a", "text": "Moderate inrush loads such as fluorescent lighting with magnetic ballasts, HID lamps, and small motor loads"}, {"id": "b", "text": "Domestic lighting circuits with only filament lamps (purely resistive)"}, {"id": "c", "text": "Stove and oven circuits"}, {"id": "d", "text": "Long heavily loaded cable runs"}]', '["a"]', 'CORRECT — Type C MCBs have magnetic trip at 5-10× nominal current. They are suitable for circuits with moderate inrush: fluorescent lighting (magnetic ballasts), HID lamps, small motors. The inrush of these loads (typically 2-4× FLA for fluorescent, 5-10× for motors) would cause nuisance tripping of Type B (3-5× In) devices. Type D (10-20× In) is for very high inrush loads (transformers, large motors). Option B — filament lamps are purely resistive with minimal inrush; Type B is appropriate. Option C — stoves/ovens are resistive; Type B or C depending on electronic controls. Option D — MCB type selection is based on load inrush, not cable length.', 'AS/NZS 60898.1; AS/NZS 3000', 4, NULL, '2026-05-09 10:36:15.901698+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('9010cb23-bdb3-5348-802a-d6b611a0614e', '647fd115-7e2c-5505-9d7c-bc0583d79045', 'In a standard motor control circuit, what is the specific protective function of a thermal overload relay compared to a magnetic circuit breaker?', '[{"id": "a", "text": "It protects the motor from sustained thermal overheating due to mechanical overload, but does not clear instantaneous short-circuit faults"}, {"id": "b", "text": "It provides instantaneous disconnection in the event of a phase-to-earth fault"}, {"id": "c", "text": "It actively limits the transient starting inrush current during a Direct-On-Line start"}, {"id": "d", "text": "It protects the upstream contactor from high-voltage inductive spikes generated during stopping"}]', '["a"]', NULL, 'AS/NZS IEC 60947-4-1', 4, NULL, '2026-05-12 08:24:59.587524+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('690f7cfb-2d66-516a-8fab-c24a82d2f3ec', '4a54f2ca-b514-539b-b086-a779d234b99f', 'Under AS/NZS 3000:2018, what is the regulatory requirement for 30mA RCD protection on final sub-circuits supplying socket-outlets within a domestic/residential installation?', '[{"id": "a", "text": "All final sub-circuits supplying socket-outlets require RCD protection regardless of their current rating"}, {"id": "b", "text": "Only socket-outlets rated up to and including 32A require RCD protection"}, {"id": "c", "text": "Only socket-outlets located outdoors or in designated damp situations require RCD protection"}, {"id": "d", "text": "Only socket-outlets rated at 10A and 15A require RCD protection"}]', '["a"]', 'CORRECT — AS/NZS 3000 Clause 2.6.2 requires RCD protection for all socket outlets rated not exceeding 20A. This covers 10A, 15A, and 20A socket outlets in ALL installation types. This is a core safety requirement because socket outlets supply portable equipment that may be handled during a fault. Option B is wrong — the 20A limit is the upper threshold, not the lower one. Option C is wrong — 15A and 20A outlets would be excluded, creating a significant safety gap. Option D is entirely wrong.', 'AS/NZS 3000:2018 Clause 2.6.2', 3, NULL, '2026-05-09 10:36:15.901698+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('78cafdca-fd08-559c-b871-39383f0148a5', '4a54f2ca-b514-539b-b086-a779d234b99f', 'An RCBO (Residual Current Breaker with Overload) provides a key advantage over a common RCD protecting multiple circuits:', '[{"id": "a", "text": "A fault on one circuit trips only that RCBO — other circuits on the same board remain energised"}, {"id": "b", "text": "RCBOs are significantly cheaper than separate RCD+MCB combinations"}, {"id": "c", "text": "RCBOs eliminate the need for coordination with upstream devices"}, {"id": "d", "text": "RCBOs can be used as main isolating switches"}]', '["a"]', 'CORRECT — The main advantage of individual RCBOs per circuit is circuit-level discrimination: a fault on one circuit trips only that RCBO; other circuits on the same distribution board remain energised. With a common RCD protecting 4 circuits, any earth fault on any circuit trips the common RCD, blacking out all 4. Option B is false — RCBOs are more expensive than separate RCD + MCB. Option C is false — coordination is still required. Option D — RCBOs are protective devices; their use as switches depends on specific marking per the standard.', 'AS/NZS 3000:2018 Clause 2.6.2; AS/NZS 61009.1', 3, NULL, '2026-05-09 10:36:15.901698+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('1ceb6e73-8a1e-561c-af1a-02ea3f5f6369', '4485a268-25ec-58de-8df8-5fa3df330063', 'In a TN-S supply system, the neutral and earth conductors are:', '[{"id": "a", "text": "Separate throughout — dedicated PE conductor runs from the transformer alongside the separate neutral conductor"}, {"id": "b", "text": "Combined as PEN from transformer to installation"}, {"id": "c", "text": "Only earthed at the transformer, never at the installation"}, {"id": "d", "text": "Connected together at every distribution point"}]', '["a"]', 'CORRECT — TN-S (Separate Neutral and Earth) has a dedicated protective earth (PE) conductor running from the transformer alongside the line and neutral conductors. The earth is established at the transformer and connected to PE. At the installation, the PE connects to the MET. This differs from TN-C-S where PEN is combined from the transformer to the point of supply. Option B describes TN-C or TN-C-S. Option C is wrong — the installation''s MEN link establishes a second earth connection. Option D is wrong — N and PE are connected only at specific points.', 'AS/NZS 3000:2018 Clause 5.2.1', 3, NULL, '2026-05-09 10:36:15.901698+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('e97f43da-b81c-5a23-87ed-ed10c1a838ea', '4485a268-25ec-58de-8df8-5fa3df330063', 'The primary purpose of the Multiple Earthed Neutral (MEN) link in a TN-C-S installation is to:', '[{"id": "a", "text": "Create a low-impedance fault return path to the supply transformer and establish the installation''s earthed exposed parts at reference potential"}, {"id": "b", "text": "Completely isolate the installation earth from the supply neutral"}, {"id": "c", "text": "Provide a neutral return path for unbalanced loads only"}, {"id": "d", "text": "Allow the main switch to be replaced without disrupting the earth path"}]', '["a"]', 'CORRECT — The MEN link connects the neutral bar to the earth bar at the main switchboard (MET). Its purposes: (1) provides a low-impedance fault current return path — without it, a line-to-earth fault cannot flow; (2) establishes exposed conductive parts at a reference potential relative to the supply neutral. Option B is wrong — the MEN link connects N and PE, not isolates them. Option C is incomplete — fault return is the primary purpose. Option D is not a purpose of the MEN link.', 'AS/NZS 3000:2018 Clause 5.2.1', 3, NULL, '2026-05-09 10:36:15.901698+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('6614df72-db04-5d67-8099-68db45a0ae3e', '4485a268-25ec-58de-8df8-5fa3df330063', 'An IT (Impedance Earthed) supply system is characterised by:', '[{"id": "a", "text": "The supply neutral is earthed through a high impedance, limiting fault current and allowing continued operation on first earth fault with an alarm"}, {"id": "b", "text": "The installation''s earth electrode is connected directly to the MEN link without impedance"}, {"id": "c", "text": "First earth fault is cleared by an RCD only"}, {"id": "d", "text": "IT is the standard system for all NZ domestic installations"}]', '["a"]', 'CORRECT — IT systems have the supply neutral either isolated (solidly IT) or connected through high impedance. The high impedance limits earth fault current, allowing the system to continue operating on a first fault (with an alarm) rather than automatically disconnecting. Used in hospitals (theatres), mines, and critical industrial facilities. Option B describes TT or TN. Option C is wrong — standard RCDs may not operate correctly on IT systems. Option D is wrong — MEN (TN-C-S) is standard in NZ.', 'AS/NZS 3000:2018 Clause 5.2.3', 3, NULL, '2026-05-09 10:36:15.901698+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('72e1da43-607a-59bc-8388-a5f5c9dc8cde', '4485a268-25ec-58de-8df8-5fa3df330063', 'In a TT earthing system, the earth fault loop impedance is typically too high to reliably operate standard overcurrent protective devices (such as MCBs) within the required disconnection times. According to AS/NZS 3000, what is the mandatory design requirement to compensate for this?', '[{"id": "a", "text": "Residual Current Devices (RCDs) must be utilized to provide earth fault protection, as they can operate effectively despite the higher earth loop impedance"}, {"id": "b", "text": "The earth electrode must be driven deeper until the measured impedance complies strictly with the maximum limits for MCBs outlined in Table 5.1"}, {"id": "c", "text": "The neutral and earth bars must be bonded together at the main switchboard to convert the installation into a TN-S system"}, {"id": "d", "text": "Earth fault clearance times are legally permitted to be extended to 5 seconds for all final sub-circuits"}]', '["a"]', 'CORRECT — In TT, the consumer installs a dedicated earth electrode (Ra) independent of the supply. The fault path is: line → earth electrode at fault → soil → consumer electrode (Ra) → soil → supply electrode → supply neutral. Zs = Ze + Ra. Ra must be low enough that Zs is within AS/NZS 3000 Table 5.1 limits. There is no fixed minimum or maximum for Ra — it is determined by the required Zs. Option B (500Ω) would be far too high for most circuit Zs requirements. Option C — Ra is independent of Ze in TT. Option D is wrong — Ra is critical in TT.', 'AS/NZS 3000:2018 Clause 5.2.2', 4, NULL, '2026-05-09 10:36:15.901698+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('33134f8d-dc04-508d-b078-5658d0f27393', '647fd115-7e2c-5505-9d7c-bc0583d79045', 'A soft starter reduces motor starting current by:', '[{"id": "a", "text": "Gradually ramping up voltage applied to the motor windings using thyristors/SCRs, limiting inrush current to 2-3× FLA vs 5-7× for DOL"}, {"id": "b", "text": "Inserting resistors in series with the motor throughout the starting sequence"}, {"id": "c", "text": "Reducing the supply frequency below 50Hz during start-up"}, {"id": "d", "text": "Using a reduced-voltage autotransformer with multiple fixed taps"}]', '["a"]', 'CORRECT — Soft starters use thyristors (SCRs) to phase-control the voltage applied to the motor. By gradually ramping voltage from a low initial value, the soft starter limits inrush current to typically 2-3× FLA (vs 5-7× for DOL). Soft starters also provide smooth torque ramp. Option B describes resistor starting, a different method. Option C describes a VFD function. Option D describes autotransformer starting, another different method.', 'AS/NZS IEC 60947-4-1', 4, NULL, '2026-05-09 10:36:15.901698+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('0480195f-47c9-515e-a712-59f832dde6d4', '647fd115-7e2c-5505-9d7c-bc0583d79045', 'A 15kW three-phase motor has nameplate FLC of 28A. The thermal overload relay should be set at:', '[{"id": "a", "text": "28A × 100-112% = 28-31A — set to the motor''s nameplate full load current per AS/NZS IEC 60947-4-1"}, {"id": "b", "text": "28A × 150% = 42A to allow for starting conditions"}, {"id": "c", "text": "28A × 80% = 22A as a conservative setting"}, {"id": "d", "text": "The overload setting depends on the cable size, not the motor rating"}]', '["a"]', 'CORRECT — AS/NZS IEC 60947-4-1: thermal overload relays set to 100-112% of motor nameplate FLC. The overload is designed to carry the motor''s rated current continuously without tripping. Option B (150%) would leave the motor unprotected against sustained overloads. Option C (80%) would cause nuisance tripping at normal full-load current. Option D is wrong — overload settings are based on motor FLC, not cable size.', 'AS/NZS IEC 60947-4-1', 3, NULL, '2026-05-09 10:36:15.901698+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('64ef1981-a299-5211-bed0-84f1c6de7c83', '647fd115-7e2c-5505-9d7c-bc0583d79045', 'A Direct On Line (DOL) started 7.5kW motor draws approximately how many times its full load current during starting?', '[{"id": "a", "text": "5-7× FLA — DOL starting produces high inrush current due to low rotor impedance at standstill"}, {"id": "b", "text": "1-2× FLA — motors start smoothly without significant current increase"}, {"id": "c", "text": "10-12× FLA — maximum current at start"}, {"id": "d", "text": "Equal to FLC — DOL has no current increase at start"}]', '["a"]', 'CORRECT — At standstill, the rotor has no back-EMF, so the stator draws very high magnetising current. Locked rotor current (LRA) for a DOL-started induction motor is typically 5-7× FLA. This causes voltage dip and must be considered in supply design. For star-delta, starting current reduces to 1/√3 ≈ 33% of DOL starting current. Option B is false. Option C (10-12×) is more typical of large special-purpose motors; 5-7× is the standard range. Option D is false.', 'AS/NZS IEC 60947-4-1; motor starting theory', 3, NULL, '2026-05-09 10:36:15.901698+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('1288d0c1-00d1-556b-beef-fb4410f47e34', '647fd115-7e2c-5505-9d7c-bc0583d79045', 'According to AS/NZS 3000 Clause 4.13.1.4, which of the following is a mandatory physical location or configuration requirement for an isolating switch serving a motor?', '[{"id": "a", "text": "Installed adjacent to the motor, or if located remotely, capable of being locked in the open (OFF) position"}, {"id": "b", "text": "Located exclusively on the main switchboard for centralized control"}, {"id": "c", "text": "A momentary pull-cord switch mounted directly above the motor terminal box"}, {"id": "d", "text": "Required only to break the control circuit current, not the primary load current"}]', '["a"]', 'CORRECT — AS/NZS 3000 Clause 2.9 and AS/NZS IEC 60204-1: motor isolators must break full load current and be within sight of the motor OR lockable in OFF position (so the motor cannot be started during maintenance). Option B is wrong — the isolator must break motor full load current, not just control circuit current. Option C is not a recognised motor isolation means. Option D is wrong — the building main switch may not be in sight of the motor and a non-lockable switch doesn''t satisfy the lockable/off-sight requirement.', 'AS/NZS 3000:2018 Clause 2.9; AS/NZS IEC 60204-1', 3, NULL, '2026-05-09 10:36:15.901698+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('8603640b-5e46-5ed0-988e-946814decac7', '72860a92-1d9b-550e-b0f8-648c5100c321', 'A switchboard busbar protected by a 400A main circuit breaker must be rated at:', '[{"id": "a", "text": "At least 400A — equal to or greater than the rating of the protective device protecting it"}, {"id": "b", "text": "150A less than the main circuit breaker rating"}, {"id": "c", "text": "The sum of all outgoing circuit protective device ratings"}, {"id": "d", "text": "Busbar rating is not specified in AS/NZS 3000"}]', '["a"]', 'CORRECT — AS/NZS 61439.1 requires busbars to be rated at least equal to the protective device protecting them. The busbar must carry the full fault current without damage. A 400A busbar protected by a 400A breaker is at its limit but compliant. Option B is not a standard rule. Option C — busbar rating is based on the upstream protective device, not the sum of downstream devices. Option D is false — AS/NZS 61439 specifies busbar rating requirements.', 'AS/NZS 61439.1; AS/NZS 3000 Clause 2.8', 4, NULL, '2026-05-09 10:36:15.901698+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('df9b2b49-b856-544e-a7f1-db682d4a823c', '72860a92-1d9b-550e-b0f8-648c5100c321', 'Segregation of circuits within a switchboard is required to:', '[{"id": "a", "text": "Prevent a fault on one circuit propagating to adjacent circuits and prevent operators contacting live parts of other circuits during fault finding"}, {"id": "b", "text": "Allow multiple circuits to share the same enclosure without any barrier"}, {"id": "c", "text": "Reduce switchboard construction cost"}, {"id": "d", "text": "Only required for circuits above 100A"}]', '["a"]', 'CORRECT — AS/NZS 61439.1 requires segregation (form separation) of circuits using barriers/partitions. Purposes: (1) operator safety — prevents contact with live parts of adjacent circuits during fault finding; (2) fault containment — prevents arc faults spreading to adjacent circuits; (3) reliability — prevents a fault on one circuit causing unintended operation of adjacent protective devices. Option B is the opposite of segregation requirements. Option C is wrong — segregation adds cost but is mandatory. Option D is wrong — requirements apply regardless of current rating.', 'AS/NZS 61439.1; AS/NZS 3000 Clause 2.8', 3, NULL, '2026-05-09 10:36:15.901698+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('86b53b8a-317b-5507-a349-53d52d791111', '72860a92-1d9b-550e-b0f8-648c5100c321', 'AS/NZS 3000 requires that the working space in front of a switchboard:', '[{"id": "a", "text": "Be maintained clear at all times — minimum clear depth of 0.6m for boards up to 250A, increasing for higher ratings"}, {"id": "b", "text": "Allow materials to be stored provided the door can open"}, {"id": "c", "text": "Be shared with telephone and data equipment if space is limited"}, {"id": "d", "text": "Only applies to industrial switchboards"}]', '["a"]', 'CORRECT — AS/NZS 3000 Clause 2.8 and AS/NZS IEC 60204-1 require a clear working space in front of switchboards. Minimum depth is 0.6m for boards up to 250A. The space must be kept clear — storage is prohibited. Option B is wrong. Option C — telephone/data equipment may not encroack on switchboard working space. Option D is wrong — requirements apply to all switchboards.', 'AS/NZS 3000:2018 Clause 2.8; AS/NZS IEC 60204-1', 3, NULL, '2026-05-09 10:36:15.901698+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('a97d5655-3f73-5794-962c-95b4dfdde585', 'ac388207-779c-5a46-a6e9-b556f0578f56', 'A ring final circuit (RFC) in a domestic installation serves primarily to:', '[{"id": "a", "text": "Provide two parallel current paths to each socket outlet, reducing voltage drop and providing redundancy if one path is broken"}, {"id": "b", "text": "Reduce the total cable required compared to a radial circuit"}, {"id": "c", "text": "Increase the fault level at each socket outlet"}, {"id": "d", "text": "Allow socket outlets to be added without recalculating demand"}]', '["a"]', 'CORRECT — The RFC runs as a complete loop from the distribution board and back. Each socket has two current paths. Key advantages: (1) reduced voltage drop — current splits between two paths, halving the current in each cable segment; (2) redundancy — if cable is damaged at one point (not both paths), all outlets remain energised via the alternate route. Option B — RFC doesn''t necessarily reduce total cable length; it allows smaller conductors due to current splitting. Option C is wrong. Option D is wrong — additions still require demand recalculation.', 'AS/NZS 3000:2018 Clause 4.2', 3, NULL, '2026-05-09 10:36:15.901698+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('337fe2ce-4409-5181-ba09-01350e85406e', 'ac388207-779c-5a46-a6e9-b556f0578f56', 'A sub-main cable feeding a distribution board with multiple different-rated outgoing circuits should be sized for:', '[{"id": "a", "text": "The maximum demand of the distribution board calculated per AS/NZS 3000 Clause 4.2 diversity factors"}, {"id": "b", "text": "The sum of all outgoing protective device ratings without diversity"}, {"id": "c", "text": "The largest single outgoing protective device rating"}, {"id": "d", "text": "The sub-main does not need separate sizing if the main is correctly sized"}]', '["a"]', 'CORRECT — Sub-mains are sized for the maximum demand of the load they serve, calculated using AS/NZS 3000 Clause 4.2 diversity factors applied to groups of circuits served. Summing all protective device ratings without diversity would significantly oversize the sub-main. Table 4.2 diversity factors reflect the fact that not all circuits operate at full load simultaneously. Option B is the common over-sizing error. Option C would potentially undersize. Option D is wrong — sub-mains must be individually assessed.', 'AS/NZS 3000:2018 Clause 4.2', 4, NULL, '2026-05-09 10:36:15.901698+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('fa9eed96-b1e9-559a-ba39-edcb0ea94c81', 'ac388207-779c-5a46-a6e9-b556f0578f56', 'According to AS/NZS 3000 requirements for standard single-phase final sub-circuits, what is the primary regulatory constraint regarding the sizing of the neutral conductor?', '[{"id": "a", "text": "The neutral conductor must have a cross-sectional area not less than that of the active conductor"}, {"id": "b", "text": "The neutral conductor must have a cross-sectional area strictly equal to half that of the active conductor to save copper"}, {"id": "c", "text": "The neutral conductor sizing is dictated solely by the measured earth fault loop impedance"}, {"id": "d", "text": "The neutral conductor must be sized one gauge larger than the active conductor to accommodate harmonic currents"}]', '["a"]', 'CORRECT — In TN-C-S (MEN), the neutral carries the unbalanced current. It must be sized for the circuit''s maximum demand — not automatically half the active size. For circuits with significant third harmonic content (common with switch-mode power supplies, LED drivers), the neutral current can exceed phase current due to harmonic triplen components, requiring the neutral to be sized accordingly or the circuit designed to handle it. The neutral must be disconnectible with the phase where required. Option B is wrong. Option C is wrong — neutral is always required. Option D is incomplete — neutral must carry the maximum demand current including harmonics.', 'AS/NZS 3000:2018 Clause 3.3; AS/NZS 3008', 4, NULL, '2026-05-09 10:36:15.901698+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('867e5698-72de-540b-af35-35537b941017', 'cd6d17a6-eac4-54af-a1b2-c443e9b8523b', 'When testing earth continuity, the resistance measured should be:', '[{"id": "a", "text": "Low enough that Vtouch = Ifault × Rearth does not exceed 50V AC — the limit depends on the protective device and fault current"}, {"id": "b", "text": "Less than 1Ω regardless of circuit length"}, {"id": "c", "text": "Equal to the phase conductor resistance"}, {"id": "d", "text": "Tested only at the main earthing conductor"}]', '["a"]', 'CORRECT — Earth continuity test ensures the protective conductor can carry fault current without producing dangerous touch voltages. The criterion is: Vtouch = Ifault × Rearth < 50V. Since Ifault for a 32A MCB on a dead-short is ~160A, Rearth must be < 50V/160A = 0.31Ω. AS/NZS 3000/3019 provide maximum earth conductor resistances per circuit/protective device. Option B (1Ω) is a rule of thumb but not the formal test criterion — for a 32A circuit the limit is ~0.3Ω. Option C is not the test basis. Option D is wrong — each circuit''s earth continuity must be tested.', 'AS/NZS 3000:2018 Clause 8.3.3; AS/NZS 3019', 4, NULL, '2026-05-09 10:36:15.901698+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('79b9e4e2-1ebc-53dc-9334-9ad5939ee53e', 'cd6d17a6-eac4-54af-a1b2-c443e9b8523b', 'Polarity testing of a single-phase circuit confirms that:', '[{"id": "a", "text": "Every switch, including the main switch, breaks the active (line) conductor only — not the neutral"}, {"id": "b", "text": "The neutral and earth are correctly identified"}, {"id": "c", "text": "All three phases are correctly sequenced in a three-phase circuit"}, {"id": "d", "text": "The circuit is connected to the correct phase of the supply"}]', '["a"]', 'CORRECT — AS/NZS 3000 Clause 8.3.6: polarity testing confirms that every switching device (including the main switch and all single-pole switches) breaks the LINE conductor only. If a switch breaks neutral, the circuit remains live even when switched off — a serious shock hazard. Option B is an identification/continuity check. Option C is phase sequence testing. Option D is a supply connection check, not the primary purpose of polarity testing per the standard.', 'AS/NZS 3000:2018 Clause 8.3.6', 3, NULL, '2026-05-09 10:36:15.901698+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('ed97f306-8012-5435-800d-da99a15e5936', 'cd6d17a6-eac4-54af-a1b2-c443e9b8523b', 'The test button on an RCD operates by:', '[{"id": "a", "text": "Injecting a calibrated fault current (typically 30mA for a 30mA RCD) through the RCD''s internal test circuit to simulate earth leakage, causing it to trip"}, {"id": "b", "text": "Forcing the RCD contacts to weld together to check mechanical operation"}, {"id": "c", "text": "Measuring the earth electrode resistance by injecting a small current"}, {"id": "d", "text": "Disabling the RCD''s electronic circuit to verify mechanical trip"}]', '["a"]', 'CORRECT — The RCD test button applies a calibrated resistance across line and earth terminals inside the RCD, injecting a simulated earth leakage current equal to the RCD''s rated trip current (e.g., 30mA for a 30mA RCD). If the RCD trips, the test circuit and trip mechanism are confirmed functional. IMPORTANT: the test button only tests the internal test circuit — it does NOT test the RCD''s ability to trip on real external earth leakage. A full functional test with an earth leakage tester is required for comprehensive RCD testing. Option B is wrong. Option C is what an earth electrode tester does. Option D is wrong.', 'AS/NZS 3000:2018 Clause 8.3.8', 3, NULL, '2026-05-09 10:36:15.901698+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('e74d2bda-0089-5a71-a519-3e714e605e3b', 'cd6d17a6-eac4-54af-a1b2-c443e9b8523b', 'Insulation resistance and earth fault loop impedance testers used for compliance testing must be:', '[{"id": "a", "text": "Calibrated with a valid test record — instrument accuracy directly affects whether compliant results are measured or borderline results missed"}, {"id": "b", "text": "New (purchased within 12 months) to ensure accuracy"}, {"id": "c", "text": "Supplied or approved by the supply authority"}, {"id": "d", "text": "Self-checking instruments that do not require calibration"}]', '["a"]', 'CORRECT — Test instrument accuracy directly affects compliance outcomes. An out-of-calibration insulation tester could miss a genuine 0.8 MΩ failure or fail a genuinely compliant 1.2 MΩ installation. AS/NZS 3019 requires test instruments to be calibrated and maintained. Calibration certificates should be current (typically 12-24 months). Option B is false — age is not the criterion; calibration status is. Option C is false. Option D is false — no test instrument is self-calibrating.', 'AS/NZS 3019; instrument calibration requirements', 3, NULL, '2026-05-09 10:36:15.901698+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('fc0a60b4-1552-5b09-a164-7aa4cfd30014', 'edfd8597-c616-5170-8a22-9ea0c3e26514', 'Personal protective equipment (PPE) for electrical work includes insulating gloves. The gloves must be:', '[{"id": "a", "text": "Rated to the appropriate voltage class and tested/poled at regular intervals not exceeding 6 months"}, {"id": "b", "text": "Leather over-gloves worn over any rubber glove for mechanical protection"}, {"id": "c", "text": "Replaced if they show any visible signs of wear or cracking"}, {"id": "d", "text": "Class 00 gloves are sufficient for all LV work below 500V"}]', '["a"]', 'CORRECT — Insulating gloves must be selected for the voltage class of the work (Class 00 through Class 4) and must be electrically tested and poled at intervals not exceeding 6 months per NZ regulations and AS/NZS 3000 requirements. Gloves that have not been tested within the required period may have invisible degradation and provide no protection — they give a false sense of safety. Pre-use inspection for physical damage is also required before each use.', 'AS/NZS 3000:2018 Clause 2.4; NZ Electricity (Safety) Regulations 2010; AS/NZS 4201', 3, NULL, '2026-05-09 10:43:22.863284+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('08339e93-8cb2-58c2-ab29-4cc1f68c32b7', 'edfd8597-c616-5170-8a22-9ea0c3e26514', 'When using a hole saw or core drill near an electrical installation, the primary hazard is:', '[{"id": "a", "text": "Contact with energised concealed cables or conduits, which may not be shown on available drawings"}, {"id": "b", "text": "Excessive noise from the drill"}, {"id": "c", "text": "Dust inhalation from cutting brick or concrete"}, {"id": "d", "text": "Damage to the hole saw from hitting concrete"}]', '["a"]', 'CORRECT — The primary hazard when drilling or cutting into walls, floors, and ceilings is accidentally cutting into concealed electrical cables. Cable drawings are often incomplete or inaccurate, especially in older installations. Before drilling, safe work practices require the electrician to: trace cable routes where possible, use a cable detector, de-energise and lock out circuits where feasible, and wear appropriate PPE. Cutting an energised cable can cause severe burns, fires, and arc flash.', 'AS/NZS 3000:2018 Clause 2.4; NZ Electricity (Safety) Regulations; Safe Work NZ', 3, NULL, '2026-05-09 10:43:22.863284+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('7fffcf8c-c300-5613-95c9-12958c4408b8', 'edfd8597-c616-5170-8a22-9ea0c3e26514', 'Lockout/Tagout (LOTO) procedures require that the lock used to secure an isolating switch in the OFF position:', '[{"id": "a", "text": "Is under the sole control of the worker who will perform the work, with a personal tag identifying the worker and work to be done"}, {"id": "b", "text": "Is owned by the site supervisor and kept in the supervisor''s office"}, {"id": "c", "text": "Is a standard lock whose key is kept in the site key cabinet"}, {"id": "d", "text": "Only needs a tag — the lock is optional if a tag is clearly visible"}]', '["a"]', 'CORRECT — Each worker must apply their own personal lock (or a lock under their sole control) to the isolation point, with a tag identifying who they are and what work is being done. This prevents another worker from accidentally re-energising the circuit while work is in progress. A group lock-box system may be used when multiple workers share an isolation. Leaving a circuit without personal lockout is a common cause of fatal accidents in electrical work.', 'AS/NZS 3000:2018 Clause 2.4; NZ Electricity (Safety) Regulations 2010; Safe Work NZ LOTO guidelines', 4, NULL, '2026-05-09 10:43:22.863284+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('3bd8e18e-a5ec-5bef-921f-058cd2ca5f33', 'edfd8597-c616-5170-8a22-9ea0c3e26514', 'When testing for voltage on a circuit that may include DC components (such as motor drives), a test instrument must:', '[{"id": "a", "text": "Be capable of measuring both AC and DC voltages and be rated for the system"}, {"id": "b", "text": "Be set to the DC voltage range before testing"}, {"id": "c", "text": "Only need to measure AC since DC circuits are rare in buildings"}, {"id": "d", "text": "Be used only after confirming with the building engineer that DC is not present"}]', '["a"]', 'CORRECT — Many modern circuits include DC components (variable speed drives, UPS systems, battery backends, DC motor controls). A standard AC-only multimeter will give incorrect or zero readings on DC circuits. A multimeter rated for both AC and DC measurement, with appropriate voltage and category rating, must be used. Additionally, some DC systems (e.g. 600V DC solar arrays) can sustain an arc that is difficult to extinguish with AC-rated equipment alone.', 'AS/NZS 3000:2018 Clause 8.2; AS/NZS 61010-1; IEEE 1584', 4, NULL, '2026-05-09 10:43:22.863284+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('c01b9853-402c-58e3-9085-a5999b1eb15c', 'cd6d17a6-eac4-54af-a1b2-c443e9b8523b', 'During the mandatory polarity testing of an installation, what is the strictly required conductor arrangement for Edison Screw (ES) lampholders?', '[{"id": "a", "text": "The active conductor must be connected to the center contact, and the neutral conductor to the outer threaded shell"}, {"id": "b", "text": "The neutral conductor must be connected to the center contact to ensure the shell remains at earth potential"}, {"id": "c", "text": "Polarity is irrelevant for lampholders as incandescent and LED lamps operate seamlessly on alternating current"}, {"id": "d", "text": "Both the active and neutral conductors must connect to the base plate, leaving the outer shell completely isolated"}]', '["a"]', NULL, 'AS/NZS 3000 Clause 8.3.5', 3, NULL, '2026-05-12 08:24:59.587524+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('6a8cf8ff-45fe-5236-b05f-e4200d2c6a00', 'edfd8597-c616-5170-8a22-9ea0c3e26514', 'The minimum approach distance for a worker to an exposed energised part at 400V three-phase is determined by:', '[{"id": "a", "text": "The voltage level and arc flash boundary calculations — NZ regulations specify minimum approach distances that must not be reduced"}, {"id": "b", "text": "What the job foreman decides is safe based on the work to be done"}, {"id": "c", "text": "The amount of space available around the equipment"}, {"id": "d", "text": "Whether the worker has worked on this equipment before"}]', '["a"]', 'CORRECT — Approach distances to energised parts are specified in NZ regulations and AS/NZS 3000. For 400V systems, the shock approach boundary (limited approach) is typically 1.0m for an electrically qualified person. The arc flash boundary is calculated separately based on fault level (IEEE 1584). Workers must not reduce approach distances without formal written authorisation and appropriate PPE. Many fatal accidents occur when workers cross approach boundaries without realising the hazard.', 'AS/NZS 3000:2018 Clause 2.4; NZ Electricity (Safety) Regulations; IEEE 1584', 3, NULL, '2026-05-09 10:43:22.863284+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('3640c7f3-8455-5a22-bf15-2e239d45f906', 'edfd8597-c616-5170-8a22-9ea0c3e26514', 'Emergency lighting in a switchroom must activate within seconds of:', '[{"id": "a", "text": "Failure of the normal lighting supply — providing a minimum of 90 minutes of illumination for safe exit"}, {"id": "b", "text": "Activation of the fire alarm system only"}, {"id": "c", "text": "Manual activation by the site supervisor"}, {"id": "d", "text": "Failure of the main supply transformer"}]', '["a"]', 'CORRECT — Emergency lighting must operate automatically upon failure of the normal supply, providing sufficient illumination (typically not less than 1 lux at floor level) for a minimum of 90 minutes. This allows workers to safely exit the switchroom in the event of a power failure or fault that causes the normal lighting to fail. Emergency lighting is tested periodically (monthly visual inspection, annual full duration test) per AS/NZS 2293.', 'AS/NZS 3000:2018 Clause 2.7; AS/NZS 2293; NZ Building Code', 3, NULL, '2026-05-09 10:43:22.863284+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('c86644ab-cede-5396-a88d-7407da2917df', '4a54f2ca-b514-539b-b086-a779d234b99f', 'Define the term DISCRIMINATION in relation to electrical protection in an electrical installation.', '[{"id": "a", "text": "The protective device CLOSEST to the fault operates before any other protective device can"}, {"id": "b", "text": "The protective device FURTHEST from the fault operates first to isolate the minimum circuit"}, {"id": "c", "text": "All protective devices in the circuit operate simultaneously to ensure complete isolation"}, {"id": "d", "text": "The main switchboard device operates before any sub-circuit device regardless of fault location"}]', '["a"]', 'CORRECT — Discrimination (selectivity) in a protection system means that when a fault occurs, only the protective device closest to the fault operates to isolate the minimum possible circuit, leaving the rest of the installation energised. This is achieved by coordinating device time-current characteristics so upstream devices have sufficient time delay to allow downstream devices to trip first. Proper discrimination minimises disruption — only the faulted circuit is affected.
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('9e264bf2-b814-566c-bed5-769f2d7b44e5', '4a54f2ca-b514-539b-b086-a779d234b99f', 'State the maximum residual current rating for an RCD installed in a patient treatment area.', '[{"id": "a", "text": "10mA"}, {"id": "b", "text": "30mA"}, {"id": "c", "text": "300mA"}, {"id": "d", "text": "100mA"}]', '["a"]', 'CORRECT — In patient treatment areas (hospital wards, theatres, dental surgeries), a maximum 10mA RCD is required for personal protection. This extremely sensitive setting is mandated because patients may be in a vulnerable physiological state (anaesthetised, surgically prepared, or with reduced pain sensitivity) and a standard 30mA RCD may not trip quickly enough to prevent cardiac arrest from fibrillation. Healthcare facilities may also have 30mA RCDs at the supply level for back-up discrimination, but the final protection at socket outlets in patient areas must be rated no higher than 10mA.
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('2808acda-d519-5290-82e3-e23c9c5b9301', 'cf002c8c-36ac-50c7-a590-36ab31e09e40', 'State TWO factors that determine the voltage drop in a 400V final subcircuit TPS cable.', '[{"id": "a", "text": "Cable length and cross-sectional area"}, {"id": "b", "text": "Ambient temperature and enclosure type"}, {"id": "c", "text": "Supply frequency and power factor"}, {"id": "d", "text": "System grounding type and fault level"}]', '["a"]', 'CORRECT — Voltage drop in a conductors is determined by V = I × R, and resistance R = ρ × L / A (where ρ = resistivity of the conductor material, L = length, A = cross-sectional area). The two practical factors under the electrician''s control are: (1) Cable length — longer run = more resistance = greater voltage drop; (2) Cross-sectional area (CSA) — larger conductor = less resistance = less voltage drop. AS/NZS 3000 Clause 3.6 and Table 3.1 govern voltage drop limits for final subcircuits (maximum 7% for motor circuits, 5% for lighting). To limit voltage drop, either shorten the run or increase the cable CSA.
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('ff967bb5-8616-5efd-82d7-db219c87bbb7', 'ac388207-779c-5a46-a6e9-b556f0578f56', 'Under the New Zealand Electricity (Safety) Regulations 2010, what is the primary legal declaration made when an electrical worker signs and issues an Electrical Safety Certificate (ESC)?', '[{"id": "a", "text": "It officially certifies that the specified electrical work has been completed, tested, and is electrically safe to connect to the power supply"}, {"id": "b", "text": "It registers the electrical worker hours for their annual Continuing Professional Development (CPD) requirements"}, {"id": "c", "text": "It serves as a commercial warranty, guaranteeing that the appliances will operate without faults for 12 months"}, {"id": "d", "text": "It acts as an application to the supply authority to request a new smart meter installation"}]', '["a"]', NULL, 'NZ Electricity (Safety) Regulations 2010', 2, NULL, '2026-05-12 08:24:59.587524+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('d28d235e-17e2-5e03-8575-954275f23e56', '061d9060-cc7d-5338-a541-044dce012e11', 'State TWO factors that determine the prospective short-circuit current in an electrical installation.', '[{"id": "a", "text": "Supply system capacity and line impedance"}, {"id": "b", "text": "Load power factor and voltage regulator setting"}, {"id": "c", "text": "Cable length and cross-sectional area only"}, {"id": "d", "text": "Ambient temperature and installation method"}]', '["a"]', 'CORRECT — Prospective short-circuit current (PSCC) is determined by two primary factors: (1) the supply system capacity and fault level at the point of supply (the source side, determined by transformer rating and network impedance), and (2) the line impedance of the supply conductors from the point of supply to the fault location. The lower these values, the higher the prospective fault current.
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('9b3f457d-4580-5a99-a21b-1d6158c0e9b7', 'edfd8597-c616-5170-8a22-9ea0c3e26514', 'An electrician is about to perform live work on a 400V distribution board. Arc flash calculation using IEEE 1584 gives an incident energy level of 25 cal/cm² at the working distance. According to AS/NZS 4509 (standalone power systems) arc flash management principles and NZ Workplace Safety guidelines, what arc flash PPE category applies?', '[{"id": "a", "text": "Category 3 — high arc flash PPE: arc-rated coverall and face shield with balaclava (25 cal/cm² minimum)"}, {"id": "b", "text": "Category 1 — basic arc flash PPE: non-melting clothing, leather gloves, safety glasses"}, {"id": "c", "text": "Category 2 — standard arc flash PPE: arc-rated shirt and trousers (8 cal/cm² minimum)"}, {"id": "d", "text": "Category 4 — maximum protection: arc-rated full suit, hood, and gloves (40 cal/cm² minimum)"}]', '["a"]', 'CORRECT — An incident energy of 25 cal/cm² falls in the Category 3 range. In NFPA 70E and AS/NZS 4509-aligned NZ standards, Category 3 requires a minimum arc rating of 25 cal/cm² and covers incident energies above 8 cal/cm² up to and including 25 cal/cm². PPE includes arc-rated coverall and face shield with balaclava. Category 4 (arc-rated full suit, hood, and gloves) is required above 25 cal/cm². Under NZ workplace safety law and AS/NZS 3000 Clause 2.4, arc flash risk assessment must determine incident energy and select appropriate PPE before live work commences. AS/NZS 3000:2018 Clause 2.4 and NZ Electricity (Safety) Regulations 2010 require this assessment.', 'AS/NZS 3000:2018 Clause 2.4; NZ Electricity (Safety) Regulations 2010; IEEE 1584', 3, NULL, '2026-05-12 03:56:19.842657+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('a489e738-158f-521a-9655-a4b41ccb1ed5', 'ac388207-779c-5a46-a6e9-b556f0578f56', 'A 2.5mm² twin and earth cable is to be installed under a house in a domestic installation, running without mechanical protection for a span of 900mm. According to AS/NZS 3000:2018, which installation method applies?', '[{"id": "a", "text": "Method 1 — open and accessible, supported at intervals not exceeding 1.2m"}, {"id": "b", "text": "Method 2 — totally enclosed in a wiring enclosure throughout"}, {"id": "c", "text": "Method 3 — totally enclosed in a solid wiring system (embedded in building fabric)"}, {"id": "d", "text": "Method 4 — installed underground or in direct contact with ground"}]', '["a"]', 'CORRECT — Method 1 applies to cables installed in accessible positions where no mechanical protection is provided. AS/NZS 3000 Clause 3.4.2 specifies that for twin and earth or similar sheathed cables not in a wiring enclosure, the method must be one of the designated methods in Table 3.1. An unsupported span of 900mm falls within the limit for Method 1 when supports are at intervals not exceeding 1.2m, and being under the house in a dry location satisfies the Method 1 environmental requirements.
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('b481db5f-a609-5650-ad4a-09c1854d851d', 'cd6d17a6-eac4-54af-a1b2-c443e9b8523b', 'When testing earth fault loop impedance on a final subcircuit supplying socket outlets, the measured value must be:', '[{"id": "a", "text": "Less than or equal to the maximum value calculated using the formula Uo/Ia, where Uo is the nominal phase voltage and Ia is the fault current required to operate the protective device within the specified disconnection time"}, {"id": "b", "text": "Less than 1Ω regardless of circuit length or protective device type"}, {"id": "c", "text": "Exactly matching the sum of the phase conductor resistance and earth conductor resistance (Ze + R1 + R2)"}, {"id": "d", "text": "Greater than the calculated maximum to provide a safety margin"}]', '["a"]', 'AS/NZS 3000:2018 Clause 8.3.9 requires that the measured earth fault loop impedance (Zs) does not exceed the maximum determined by the formula Zs = Uo/Ia. Uo is the nominal single-phase voltage (230 V in NZ), and Ia is the current that causes the protective device to operate within the specified disconnection time — for socket outlets, this maximum disconnection time is 0.4 seconds (Clause 2.4). The 1\u03a9 figure (Option B) is not a universal standard; it is a rule-of-thumb used only for certain RCD trip tests, not for earth fault loop impedance compliance. Option C is incorrect because Zs is a measured value, not a simple addition of conductor resistances — it includes the source impedance, connections, and temperature corrections. Option D is incorrect because exceeding the calculated maximum means the protective device may fail to clear a fault within the required time, creating a safety hazard rather than a safety margin.', 'AS/NZS 3000:2018 Clause 8.3.9; Clause 2.4 (disconnection times)', 3, NULL, '2026-05-12 03:56:19.842657+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('30c6f7d0-c921-5816-8305-8d68c26b0466', '061d9060-cc7d-5338-a541-044dce012e11', 'In relation to earth fault loop impedance (Zs), how does a significant increase in the physical length of a final subcircuit affect the safety of the circuit?', '[{"id": "a", "text": "Increasing the circuit length increases the total impedance, which reduces the fault current and may prevent the protective device from tripping within the required disconnection time"}, {"id": "b", "text": "Increasing the circuit length decreases the impedance, which can cause nuisance tripping of the upstream RCD during normal operation"}, {"id": "c", "text": "Circuit length has no effect on earth fault loop impedance, provided the cable current-carrying capacity is appropriately derated"}, {"id": "d", "text": "Increasing the circuit length automatically increases the local supply voltage to compensate for the physical drop"}]', '["a"]', NULL, 'AS/NZS 3000 Clause 8.3.9', 3, NULL, '2026-05-12 08:24:59.587524+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('f0aec700-0499-55dd-a65e-fd47a7c37626', '72860a92-1d9b-550e-b0f8-648c5100c321', 'According to AS/NZS 3000, a fixed electrical appliance that is NOT readily accessible must be provided with an isolation switch that is:', '[{"id": "a", "text": "Readily accessible to the user and capable of isolating all active conductors including the neutral"}, {"id": "b", "text": "Mounted inside the appliance controller enclosure for security"}, {"id": "c", "text": "Only required if the appliance rating exceeds 30A"}, {"id": "d", "text": "Located at the main switchboard only"}]', '["a"]', 'CORRECT — AS/NZS 3000 Clause 2.8 requires that any fixed appliance not in readily accessible reach must have an isolation switch installed adjacent to the appliance. The switch must be readily accessible and must isolate all active conductors including the neutral (double pole). This allows a person to isolate the appliance safely without needing to go to the main switchboard or access the appliance itself. Option B is wrong — mounting the switch inside the controller does not satisfy the accessibility requirement. Option C is wrong — there is no 30A threshold exemption for non-readily accessible fixed appliances; the requirement applies to all such appliances regardless of rating. Option D is wrong — an isolation switch must be located adjacent to the appliance it controls, not at the main switchboard, to allow safe local isolation.', 'AS/NZS 3000:2018 Clause 2.8', 3, NULL, '2026-05-12 03:56:19.842657+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('3cbf4ec9-938e-5481-ba55-44a289385012', '72860a92-1d9b-550e-b0f8-648c5100c321', 'A fixed 3.0kW 230V storage hot water cylinder is installed in a plant room. According to AS/NZS 3000 Clause 2.8, the minimum rating for the isolation switch installed adjacent to the cylinder is:', '[{"id": "a", "text": "16A"}, {"id": "b", "text": "20A"}, {"id": "c", "text": "32A"}, {"id": "d", "text": "10A"}]', '["a"]', 'CORRECT — For a 3.0kW 230V load, current = 3000 ÷ 230 = 13.0A. AS/NZS 3000 Clause 2.8 requires the isolation switch rating to be at least the circuit design current, with the next standard switch rating above calculated current. Standard switch ratings are 10A, 16A, 20A, 32A, etc. — 16A is the lowest rating that accommodates 13A safely. Option B (20A) is acceptable but exceeds the minimum requirement. Option C (32A) is unnecessarily oversized. Option D (10A) is below the calculated current of 13A and does not provide adequate capacity. The isolation switch must be readily accessible, capable of being locked in the OFF position, and rated for the full load current of the appliance it serves.
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('9fb00d29-2f98-5c21-83e6-d2657eda8a27', '32b93254-79c6-5d4d-b9b1-ca2e1fa2a440', 'According to AS/NZS 3000, what is the minimum required depth of cover for a Category A underground wiring system (e.g., standard TPS cable enclosed in heavy-duty conduit) installed in a general residential area?', '[{"id": "a", "text": "500mm"}, {"id": "b", "text": "300mm"}, {"id": "c", "text": "600mm"}, {"id": "d", "text": "150mm"}]', '["a"]', NULL, 'AS/NZS 3000 Table 3.6', 3, NULL, '2026-05-12 08:24:59.587524+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('24200768-5b81-5a69-80e6-7bf5939c8640', '32b93254-79c6-5d4d-b9b1-ca2e1fa2a440', 'When installing electrical equipment within Zone 1 of a domestic bath or shower area, what is the minimum acceptable Degree of Protection (IP rating) required by AS/NZS 3000, assuming no water jets are used for cleaning?', '[{"id": "a", "text": "IPX4"}, {"id": "b", "text": "IPX7"}, {"id": "c", "text": "IPX2"}, {"id": "d", "text": "IP2X"}]', '["a"]', NULL, 'AS/NZS 3000 Clause 6.2.4', 3, NULL, '2026-05-12 08:24:59.587524+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('a0c1c285-b513-5850-9af1-c740e70d2d69', '4485a268-25ec-58de-8df8-5fa3df330063', 'In a standard New Zealand TN-C-S installation, what is the regulatory requirement for the cross-sectional area of the Multiple Earthed Neutral (MEN) link?', '[{"id": "a", "text": "It must have a cross-sectional area not less than that of the main earthing conductor"}, {"id": "b", "text": "It must be exactly half the cross-sectional area of the consumer mains neutral conductor"}, {"id": "c", "text": "It is a fixed size of 6mm² for all domestic installations regardless of main size"}, {"id": "d", "text": "It must be equal to the largest active sub-main conductor in the installation"}]', '["a"]', NULL, 'AS/NZS 3000 Clause 5.3.5.3', 3, NULL, '2026-05-12 08:24:59.587524+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('e58451f8-9d15-5ed4-8969-73db65f7c473', '1b3cf5db-12ef-59aa-9127-e3d6dcb35a2f', 'In a grid-connected Solar Photovoltaic (PV) system, where does the governing standard dictate the inverter DC isolator must be physically located?', '[{"id": "a", "text": "Adjacent to the inverter and readily accessible"}, {"id": "b", "text": "Inside the main switchboard exclusively"}, {"id": "c", "text": "On the roof, directly bolted to the solar panel array framing"}, {"id": "d", "text": "Within the utility revenue metering enclosure"}]', '["a"]', NULL, 'AS/NZS 5033; AS/NZS 3000', 4, NULL, '2026-05-12 08:24:59.587524+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('64983cc0-b6e5-56fe-9a60-b6017395e835', '72860a92-1d9b-550e-b0f8-648c5100c321', 'According to AS/NZS 3000, what are the mandatory identification and labelling requirements for the main switch controlling a low-voltage electrical installation?', '[{"id": "a", "text": "It must be clearly marked \"MAIN SWITCH\" and be readily distinguishable from all other switchgear"}, {"id": "b", "text": "It must always feature a red toggle on a yellow background, regardless of board size"}, {"id": "c", "text": "It must be painted completely green to indicate a safe isolation point for emergency services"}, {"id": "d", "text": "It is only required to be labelled if the installation exceeds 63A per phase"}]', '["a"]', NULL, 'AS/NZS 3000 Clause 2.3.3.4', 2, NULL, '2026-05-12 08:24:59.587524+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('fd19335f-61a1-5c40-9c12-f55677e8ea62', 'ac388207-779c-5a46-a6e9-b556f0578f56', 'When installing a local isolation switch for a domestic cooking appliance (e.g., an electric cooktop), what is a critical location restriction under AS/NZS 3000?', '[{"id": "a", "text": "It must not be mounted in a position that requires a person to reach across the open cooking surfaces to operate the switch"}, {"id": "b", "text": "It must be installed inside an adjacent enclosed cupboard to maintain architectural aesthetic compliance"}, {"id": "c", "text": "It must be placed at a minimum height of 2.0 meters above the finished floor level to prevent child access"}, {"id": "d", "text": "It must be located directly on the main switchboard, rendering local kitchen isolation unnecessary"}]', '["a"]', NULL, 'AS/NZS 3000 Clause 4.3.1', 3, NULL, '2026-05-12 08:24:59.587524+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('b0e6f2e3-e02d-517d-b968-87d4aa6685ed', '33c66c01-f417-510d-be43-101e18e33a5d', 'Under the New Zealand Electricity (Safety) Regulations 2010, which of the following activities is legally classified as \\"Prescribed Electrical Work\\" (PEW) requiring appropriate EWRB registration or an explicit exemption?', '[{"id": "a", "text": "Installing, extending, or altering fixed wiring within a low-voltage electrical installation"}, {"id": "b", "text": "Resetting a tripped miniature circuit breaker (MCB) on a domestic switchboard"}, {"id": "c", "text": "Replacing a blown rewireable fuse link on an existing final subcircuit"}, {"id": "d", "text": "Plugging an approved, commercially manufactured extension lead into a wall socket"}]', '["a"]', NULL, 'NZ Electricity (Safety) Regulations 2010 Schedule 1', 2, NULL, '2026-05-12 08:24:59.587524+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('2ead7172-0f4f-5947-88b2-5d8b86f6cec9', '0a093bc7-b34e-561b-87be-c1acae0e9fc0', 'In New Zealand, a recessed downlight carries an official \\"IC-F\\" classification. What does this specific classification legally permit regarding its installation within a ceiling cavity?', '[{"id": "a", "text": "The luminaire can abut and be entirely covered by standard building thermal insulation without causing a fire hazard"}, {"id": "b", "text": "The luminaire must strictly maintain a 100mm clearance from all combustible building elements at all times"}, {"id": "c", "text": "The luminaire is inherently safe to install completely submerged underwater in Zone 0 of a swimming pool"}, {"id": "d", "text": "The luminaire requires a dedicated 300mA RCD due to dangerously high internal operating temperatures"}]', '["a"]', NULL, 'AS/NZS 3000; NZ Building Code Clause F4', 3, NULL, '2026-05-12 08:24:59.587524+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('c5816ba6-6b05-5986-83c0-ce2c75c2fbce', '4b09cc13-dedd-58f5-880c-9d460f74562e', 'In alternating current (AC) circuit theory, how is \\"Power Factor\\" mathematically defined?', '[{"id": "a", "text": "The ratio of True Power (kW) to Apparent Power (kVA)"}, {"id": "b", "text": "The arithmetic sum of Reactive Power (kVAR) and True Power (kW)"}, {"id": "c", "text": "The difference between the peak voltage and the root-mean-square (RMS) voltage"}, {"id": "d", "text": "The total inductive reactance divided by the total capacitive reactance"}]', '["a"]', NULL, 'Basic AC theory; AS/NZS 3000', 2, NULL, '2026-05-12 08:24:59.587524+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('39645464-908b-5976-9996-e3f8d3e80860', '4485a268-25ec-58de-8df8-5fa3df330063', 'Under AS/NZS 3000 Table 5.2, what is the minimum required diameter for a standard copper-clad steel rod driven into the earth to serve as a main earth electrode?', '[{"id": "a", "text": "12mm"}, {"id": "b", "text": "10mm"}, {"id": "c", "text": "16mm"}, {"id": "d", "text": "8mm"}]', '["a"]', NULL, 'AS/NZS 3000 Table 5.2', 3, NULL, '2026-05-12 08:24:59.587524+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('fc3f5c59-8df0-5ecc-a4d7-3e3ff94dcab4', 'cf002c8c-36ac-50c7-a590-36ab31e09e40', 'According to AS/NZS 3000, what is the absolute maximum permissible voltage drop from the point of supply to any load point within an electrical installation?', '[{"id": "a", "text": "5% of the nominal supply voltage"}, {"id": "b", "text": "3% of the nominal supply voltage"}, {"id": "c", "text": "7% of the nominal supply voltage"}, {"id": "d", "text": "10% of the nominal supply voltage"}]', '["a"]', NULL, 'AS/NZS 3000 Clause 3.6.2(a)', 2, NULL, '2026-05-12 08:24:59.587524+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('bf5f8eee-8c2b-5c94-85f1-28165da3ee24', 'edfd8597-c616-5170-8a22-9ea0c3e26514', 'Under standard electrical safety and emergency rescue protocols, what is the absolute first action a worker must take upon discovering a colleague actively receiving a low-voltage electrical shock?', '[{"id": "a", "text": "Isolate the electrical supply to the circuit before attempting any physical contact or rescue"}, {"id": "b", "text": "Grab the victim firmly by their clothing and pull them physically away from the live conductor"}, {"id": "c", "text": "Immediately commence CPR while the victim remains in contact with the fault"}, {"id": "d", "text": "Wait for the circuit breaker or RCD to automatically trip before approaching"}]', '["a"]', NULL, 'NZ Electricity (Safety) Regulations 2010; AS/NZS 3000 Clause 2.4', 2, NULL, '2026-05-12 08:24:59.587524+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('fa19dee3-e878-577c-bb9a-6ab5f4268ca9', '061d9060-cc7d-5338-a541-044dce012e11', 'According to Ohm Law and AS/NZS 3000 requirements, what happens to the maximum permissible earth fault loop impedance (Zs) limit when the rating of the protective Miniature Circuit Breaker (MCB) is increased (e.g., upgrading from a 16A to a 20A breaker)?', '[{"id": "a", "text": "The maximum permissible Zs decreases, because a lower circuit impedance is required to generate the higher fault current necessary to trip the larger breaker instantaneously"}, {"id": "b", "text": "The maximum permissible Zs increases to limit the thermal stress placed on the larger circuit breaker"}, {"id": "c", "text": "The maximum permissible Zs remains completely identical, as loop impedance is independent of breaker rating"}, {"id": "d", "text": "The maximum permissible Zs is dictated solely by the local supply transformer and cannot be altered by circuit breaker selection"}]', '["a"]', NULL, 'AS/NZS 3000 Table 5.1; Ohm Law', 3, NULL, '2026-05-12 08:24:59.587524+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('d403bf6f-2b30-5bf2-b21c-a648605a913e', '0a093bc7-b34e-561b-87be-c1acae0e9fc0', 'According to the default clearance requirements in AS/NZS 3000 Section 4 for a recessed halogen luminaire that lacks a specific IC or CA thermal classification, what is the minimum required clearance distance above the luminaire to bulk thermal insulation?', '[{"id": "a", "text": "200mm"}, {"id": "b", "text": "50mm"}, {"id": "c", "text": "100mm"}, {"id": "d", "text": "0mm (it can be safely covered without restriction)"}]', '["a"]', NULL, 'AS/NZS 3000 Section 4; Figure 4.9', 3, NULL, '2026-05-12 08:24:59.587524+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('43297162-fe62-5166-8e4e-b07705345cfa', '061d9060-cc7d-5338-a541-044dce012e11', 'A 32A Type C Miniature Circuit Breaker (MCB) protects a 230V sub-main. Assuming a Type C breaker requires 7.5 times its rated current to guarantee instantaneous magnetic tripping, calculate the absolute maximum allowable Earth Fault Loop Impedance (Zs) in Ohms. Provide your answer to two decimal places.', NULL, '{"unit": "Ω", "answers": ["0.96", "0.95"], "tolerance": 0.02}', 'VERIFIED. Tripping current (Ia) = 32A x 7.5 = 240A. Zs = Uo / Ia. Zs = 230V / 240A = 0.958 ohms, rounding to 0.96 ohms.', NULL, 3, NULL, '2026-05-12 13:49:54.773386+00', 'exact_value');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('89721c93-81ff-5afe-b3ba-e2c099e76313', '4a54f2ca-b514-539b-b086-a779d234b99f', 'Under the latest amendments to AS/NZS 3000:2018, which type of Residual Current Device (RCD) is now the mandated minimum standard for general final subcircuits in domestic installations to handle the presence of electronic equipment?', '[{"id": "a", "text": "Type A — designed to operate on both residual sinusoidal alternating currents and residual pulsating direct currents"}, {"id": "b", "text": "Type AC — designed to operate exclusively on residual sinusoidal alternating currents"}, {"id": "c", "text": "Type S — a specifically time-delayed device used strictly for upstream discrimination"}, {"id": "d", "text": "Type B — designed specifically for smooth, ripple-free direct currents from solar arrays"}]', '["a"]', NULL, 'AS/NZS 3000:2018 Clause 2.6.2.2.2', 4, NULL, '2026-05-12 08:24:59.587524+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('5fdad608-66f9-5b1e-907a-6cc2ff6174a3', '1b3cf5db-12ef-59aa-9127-e3d6dcb35a2f', 'When installing a standby petrol generator to supply an entire domestic installation during a utility grid failure, what is the mandatory operational requirement for the manual changeover switch?', '[{"id": "a", "text": "It must be a break-before-make switch that simultaneously disconnects all active and neutral conductors from the utility supply before connecting the generator"}, {"id": "b", "text": "It must connect the generator directly in parallel with the utility mains to allow for a seamless, uninterruptible transfer of power"}, {"id": "c", "text": "It only needs to isolate the active conductors; the utility neutral must remain permanently connected to the generator neutral"}, {"id": "d", "text": "It must be an automatic motorized transfer switch (ATS) rated at no less than 100A, regardless of the generator actual output capacity"}]', '["a"]', NULL, 'AS/NZS 3000 Clause 7.3', 4, NULL, '2026-05-12 08:24:59.587524+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('fbdf8946-5a13-5415-baea-fee3ad843053', '32b93254-79c6-5d4d-b9b1-ca2e1fa2a440', 'According to AS/NZS 3000, what is the maximum permitted distance between structural supports (e.g., saddle clips) when installing a standard TPS cable (under 15mm in diameter) horizontally on a surface?', '[{"id": "a", "text": "300mm"}, {"id": "b", "text": "400mm"}, {"id": "c", "text": "600mm"}, {"id": "d", "text": "1000mm"}]', '["a"]', NULL, 'AS/NZS 3000 Table 3.3', 3, NULL, '2026-05-12 08:24:59.587524+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('0e937912-a2ee-5360-9882-c6744cf6712d', '33c66c01-f417-510d-be43-101e18e33a5d', 'Under the New Zealand Electricity Act 1992 and EWRB supervision guidelines, who holds the ultimate legal accountability for the safety, compliance, and final testing of Prescribed Electrical Work (PEW) carried out by an electrical apprentice?', '[{"id": "a", "text": "The registered electrical worker who is actively supervising the apprentice"}, {"id": "b", "text": "The apprentice performing the physical wiring work"}, {"id": "c", "text": "The homeowner or client who commissioned the electrical installation"}, {"id": "d", "text": "The local electrical supply authority inspector who issues the smart meter"}]', '["a"]', NULL, 'NZ Electricity Act 1992; EWRB supervision guidelines', 2, NULL, '2026-05-12 08:24:59.587524+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('9fc092e7-9a87-5941-a54b-8d281ad39350', '4b09cc13-dedd-58f5-880c-9d460f74562e', 'A single-phase step-down transformer has 1000 turns on its primary coil and 100 turns on its secondary coil. If the primary voltage is supplied at 230V AC, what is the theoretical secondary voltage output (ignoring core losses)?', '[{"id": "a", "text": "23V AC"}, {"id": "b", "text": "2300V AC"}, {"id": "c", "text": "115V AC"}, {"id": "d", "text": "10V AC"}]', '["a"]', NULL, 'Basic AC theory — transformer turns ratio', 2, NULL, '2026-05-12 08:24:59.587524+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('1d76ef98-21d9-5c50-a4c5-13cf0f846ce2', 'cd6d17a6-eac4-54af-a1b2-c443e9b8523b', 'During a live Earth Fault Loop Impedance (Zs) test using an active test instrument, the standard procedure requires measuring the impedance between which two specific points at the furthest socket-outlet?', '[{"id": "a", "text": "The Active (Line) pin and the Earth pin"}, {"id": "b", "text": "The Active (Line) pin and the Neutral pin"}, {"id": "c", "text": "The Neutral pin and the Earth pin"}, {"id": "d", "text": "Between the Earth pin and the main switchboard metallic enclosure"}]', '["a"]', NULL, 'AS/NZS 3000 Clause 8.3.9; test instrument manufacturer instructions', 3, NULL, '2026-05-12 08:24:59.587524+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('060c43e2-d784-567c-b10f-6c605b7283ee', '1b3cf5db-12ef-59aa-9127-e3d6dcb35a2f', 'In relation to hazardous areas and explosive atmospheres (such as petrol stations or chemical plants), how is a Zone 0 area strictly defined under the governing AS/NZS standards?', '[{"id": "a", "text": "An area in which an explosive gas atmosphere is present continuously, or for long periods, or frequently"}, {"id": "b", "text": "An area in which an explosive gas atmosphere is likely to occur occasionally during normal operation"}, {"id": "c", "text": "An area in which an explosive gas atmosphere is not likely to occur in normal operation, and if it does, it will only exist for a short time"}, {"id": "d", "text": "An area strictly containing combustible dusts but no flammable gases or vapours"}]', '["a"]', NULL, 'AS/NZS 60079 series (IEC 60079)', 4, NULL, '2026-05-12 08:24:59.587524+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('359b3288-ce3f-594a-a8e5-501ceee7aad5', '32b93254-79c6-5d4d-b9b1-ca2e1fa2a440', 'According to AS/NZS 3000, what is the exact horizontal dimension of Zone 2 extending outward from the internal rim of a standard domestic bathtub?', '[{"id": "a", "text": "0.6 metres (600mm)"}, {"id": "b", "text": "1.2 metres (1200mm)"}, {"id": "c", "text": "0.3 metres (300mm)"}, {"id": "d", "text": "1.0 metre (1000mm)"}]', '["a"]', NULL, 'AS/NZS 3000 Figure 6.2; Clause 6.2.4', 3, NULL, '2026-05-12 08:24:59.587524+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('b700618a-f74e-50da-a3b5-33f510e2e79e', '33c66c01-f417-510d-be43-101e18e33a5d', 'Under the New Zealand Electricity (Safety) Regulations 2010, when a trainee/apprentice completes a section of Prescribed Electrical Work (PEW), who is legally required to verify the work and conduct the mandatory dead testing before it is connected to a power supply?', '[{"id": "a", "text": "The registered electrical worker who is actively supervising the trainee"}, {"id": "b", "text": "The trainee themselves, provided they have successfully passed their second-year EWRB exams"}, {"id": "c", "text": "An independent electrical inspector employed by the local network utility company"}, {"id": "d", "text": "The registered electrical worker, but only if the work involves alterations to the main switchboard"}]', '["a"]', NULL, 'NZ Electricity (Safety) Regulations 2010; EWRB supervision requirements', 2, NULL, '2026-05-12 08:24:59.587524+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('0dbc586d-3a5b-5f10-8417-9965316d063a', 'cd6d17a6-eac4-54af-a1b2-c443e9b8523b', 'According to AS/NZS 3000 Chapter 8, which of the following represents the strictly mandated sequential order for dead testing a newly installed electrical circuit?', '[{"id": "a", "text": "Earth continuity, then Insulation resistance, then Polarity, then Correct circuit connections"}, {"id": "b", "text": "Insulation resistance, then Earth continuity, then Correct circuit connections, then Polarity"}, {"id": "c", "text": "Polarity, then Earth continuity, then Correct circuit connections, then Insulation resistance"}, {"id": "d", "text": "Correct circuit connections, then Polarity, then Insulation resistance, then Earth continuity"}]', '["a"]', NULL, 'AS/NZS 3000 Clause 8.3.2', 4, NULL, '2026-05-12 08:24:59.587524+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('d62a85b9-cb4c-5d48-abb1-39a3503b7dc5', 'cf002c8c-36ac-50c7-a590-36ab31e09e40', 'When calculating the voltage drop for a circuit utilizing the standard formula Vd = (L x I x Vc) / 1000, what specific metric does the Vc factor represent?', '[{"id": "a", "text": "The millivolts drop per ampere per metre of the specific cable being evaluated"}, {"id": "b", "text": "The total connected voltage of the load appliance in kilowatts"}, {"id": "c", "text": "The velocity constant of the copper conductors under maximum thermal stress"}, {"id": "d", "text": "The phase-to-neutral voltage of the local supply transformer"}]', '["a"]', NULL, 'AS/NZS 3008 Table 1-3', 3, NULL, '2026-05-12 08:24:59.587524+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('c7fdb6b1-8dcf-5d3d-90b5-99b27032d627', 'ac388207-779c-5a46-a6e9-b556f0578f56', 'Under the switchboard installation constraints of AS/NZS 3000, what is the maximum permitted height from the ground, floor, or platform to the operating face of any switchboard protective devices or isolators?', '[{"id": "a", "text": "2.0 metres"}, {"id": "b", "text": "1.2 metres"}, {"id": "c", "text": "2.5 metres"}, {"id": "d", "text": "1.5 metres"}]', '["a"]', NULL, 'AS/NZS 3000 Clause 2.10.2.4', 3, NULL, '2026-05-12 08:24:59.587524+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('5d63ce93-2066-583a-9111-0152de3b6c04', '0a093bc7-b34e-561b-87be-c1acae0e9fc0', 'A recessed downlight is officially marked with a CA90 classification. According to AS/NZS 3000, what does this specific classification indicate regarding its installation in a ceiling space?', '[{"id": "a", "text": "It may abut against normally flammable building elements, but it cannot be covered by thermal insulation, and may operate up to 90C"}, {"id": "b", "text": "It can be completely buried under bulk thermal insulation without any restrictions or clearance requirements"}, {"id": "c", "text": "It is designed exclusively for commercial applications and requires a strict 90mm physical clearance from all surrounding materials"}, {"id": "d", "text": "It must strictly be installed in concrete or masonry ceilings to prevent fire propagation"}]', '["a"]', NULL, 'AS/NZS 3000 Section 4; NZ Building Code Clause F4', 3, NULL, '2026-05-12 08:24:59.587524+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('c88113f1-0e15-533c-ad04-63186146de9a', '08a18891-41e0-5ebe-86d4-86aecf47cf61', 'When conducting an insulation resistance test on a large installation containing multiple fixed heating appliances that cannot be easily disconnected, AS/NZS 3000 permits the minimum acceptable resistance value for the complete installation to be reduced to:', '[{"id": "a", "text": "0.01 M ohm"}, {"id": "b", "text": "0.5 M ohm"}, {"id": "c", "text": "2.0 M ohm"}, {"id": "d", "text": "100 k ohm"}]', '["a"]', NULL, 'AS/NZS 3000 Clause 8.3.6.2', 4, NULL, '2026-05-12 08:24:59.587524+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('9d15c2d2-43e9-5d17-88f7-00d019a19a05', '061d9060-cc7d-5338-a541-044dce012e11', 'In an IT (Isolated Terra) earthing system, why is Earth Fault Loop Impedance (Zs) NOT utilized as the primary method to automatically disconnect the supply during a first phase-to-earth fault?', '[{"id": "a", "text": "Because the supply source is intentionally isolated from earth (or earthed through a high impedance), meaning the first fault current is too low to operate a standard overcurrent device"}, {"id": "b", "text": "Because IT systems exclusively use direct current (DC), which does not rely on loop impedance for fault clearing"}, {"id": "c", "text": "Because IT systems are only permitted for extra-low voltage (ELV) applications where fault clearance is not legally required"}, {"id": "d", "text": "Because IT systems rely entirely on the high resistance of the surrounding soil to absorb the fault energy without tripping"}]', '["a"]', NULL, 'AS/NZS 3000 Clause 3.4; IEC 60364', 4, NULL, '2026-05-12 08:24:59.587524+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('558f8f45-d8ca-59b8-86a5-8368462ae0e4', 'cf002c8c-36ac-50c7-a590-36ab31e09e40', 'Under AS/NZS 3000, the maximum permissible voltage drop for a standard low-voltage installation is 5% of the nominal supply voltage. For a standard New Zealand 230V single-phase final subcircuit, what is this maximum allowable voltage drop expressed in volts?', '[{"id": "a", "text": "11.5V"}, {"id": "b", "text": "23.0V"}, {"id": "c", "text": "12.0V"}, {"id": "d", "text": "5.0V"}]', '["a"]', NULL, 'AS/NZS 3000 Clause 3.6.2(a)', 2, NULL, '2026-05-12 08:24:59.587524+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('5de43eed-0af4-5597-8f51-ecd242c306bb', '4b09cc13-dedd-58f5-880c-9d460f74562e', 'Which mathematical formula correctly calculates the Total True Power (P, measured in Watts) consumed in a balanced three-phase alternating current (AC) circuit?', '[{"id": "a", "text": "P = sqrt(3) x V_L x I_L x cos theta"}, {"id": "b", "text": "P = 3 x V_L x I_L x sin theta"}, {"id": "c", "text": "P = sqrt(3) x V_L x I_L"}, {"id": "d", "text": "P = V_L x I_L x cos theta"}]', '["a"]', NULL, 'Basic AC theory — three-phase power', 2, NULL, '2026-05-12 08:24:59.587524+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('7fbfd3bf-71f9-54b2-a4d7-88ba9c4f5219', '4a54f2ca-b514-539b-b086-a779d234b99f', 'According to AS/NZS 3000 and specific EV charging standards, in which of the following applications is a Type B Residual Current Device (RCD) explicitly required to ensure safe operation?', '[{"id": "a", "text": "Circuits supplying electric vehicle (EV) charging equipment that lacks built-in 6mA DC fault protection"}, {"id": "b", "text": "Standard domestic indoor lighting circuits"}, {"id": "c", "text": "Commercial three-phase electric water heating circuits"}, {"id": "d", "text": "Sub-mains supplying purely resistive domestic oven loads"}]', '["a"]', NULL, 'AS/NZS 3000:2018 Clause 2.6.2.2.2; IEC 62955', 4, NULL, '2026-05-12 08:24:59.587524+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('ca7fa498-f14b-5e7d-b8e2-51362ae0fcd2', '0a093bc7-b34e-561b-87be-c1acae0e9fc0', 'According to the default clearance requirements in AS/NZS 3000 Section 4, what is the minimum required horizontal clearance between an unclassified recessed halogen luminaire and structural timber elements within a ceiling space?', '[{"id": "a", "text": "100mm"}, {"id": "b", "text": "50mm"}, {"id": "c", "text": "200mm"}, {"id": "d", "text": "0mm"}]', '["a"]', NULL, 'AS/NZS 3000 Figure 4.9; Section 4', 3, NULL, '2026-05-12 08:24:59.587524+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('2bf66846-bcda-5991-b704-4ef412592d21', '4485a268-25ec-58de-8df8-5fa3df330063', 'When supplying an outbuilding (e.g., a detached garage) from a domestic main switchboard via a sub-main, under what specific condition does AS/NZS 3000 permit a separate Multiple Earthed Neutral (MEN) link to be installed at the outbuilding distribution board?', '[{"id": "a", "text": "Only if the outbuilding has its own independent earth electrode installed and the sub-main does NOT include a continuous protective earth conductor from the main switchboard"}, {"id": "b", "text": "It is strictly prohibited in all circumstances; only one single MEN link is legally allowed per property"}, {"id": "c", "text": "Whenever the outbuilding local distribution board exceeds a 32A total capacity"}, {"id": "d", "text": "Only if the sub-main cable is buried directly in the ground rather than strung overhead"}]', '["a"]', NULL, 'AS/NZS 3000 Clause 5.5.3.1', 4, NULL, '2026-05-12 08:24:59.587524+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('e0581f90-f1f8-58e0-804c-9986053d284d', '647fd115-7e2c-5505-9d7c-bc0583d79045', 'During a Star-Delta motor starting sequence, the line current drawn from the supply while the motor is connected in the Star configuration is reduced to what mathematical fraction of the current that would be drawn if it were started Direct-On-Line (Delta)?', '[{"id": "a", "text": "One-third (1/3) of the Direct-On-Line starting line current"}, {"id": "b", "text": "One-half (1/2) of the Direct-On-Line starting line current"}, {"id": "c", "text": "Equal to the Direct-On-Line starting line current, but with a corrected power factor"}, {"id": "d", "text": "Two-thirds (2/3) of the Direct-On-Line starting line current"}]', '["a"]', NULL, 'Basic motor theory — star-delta starting', 4, NULL, '2026-05-12 08:24:59.587524+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('e78dddee-6a60-5681-bb82-5d61e10d9f9d', 'edfd8597-c616-5170-8a22-9ea0c3e26514', 'What is the legally mandated safety procedure (often referred to as Test Before You Touch) to verify that an isolated circuit is genuinely dead and safe to work on?', '[{"id": "a", "text": "Test the voltage instrument on a known live source, test the isolated circuit to confirm zero voltage, and then re-test the instrument on the known live source to verify it is still functioning correctly"}, {"id": "b", "text": "Turn the isolation switch off, attach a personal LOTO tag, and immediately begin physical work without testing"}, {"id": "c", "text": "Check that the red neon indicator light on the main switchboard has turned off"}, {"id": "d", "text": "Run a non-contact voltage stick (Volt-stick) over the outer PVC sheath of the cable to check for magnetic fields"}]', '["a"]', NULL, 'NZ Electricity (Safety) Regulations 2010; AS/NZS 3000 Clause 2.4; EWRB safe working guidelines', 2, NULL, '2026-05-12 08:24:59.587524+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('5f9c4e35-a27a-5267-958e-a1c5eef575e4', '061d9060-cc7d-5338-a541-044dce012e11', 'A 230V final subcircuit is protected by a 20A Type C Miniature Circuit Breaker (MCB). Assuming the magnetic trip multiplier for a Type C device is 7.5x the rated current, calculate the maximum permissible Earth Fault Loop Impedance (Zs) required to achieve instantaneous tripping. Provide your answer to two decimal places.', NULL, '{"unit": "Ω", "answers": ["1.53"], "tolerance": 0.05}', 'VERIFIED. I_a = 20A x 7.5 = 150A. Zs = Uo / I_a = 230V / 150A = 1.533 ohms.', NULL, 3, NULL, '2026-05-12 13:49:54.773386+00', 'exact_value');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('aa41148e-d7a8-5b95-8ee5-8020fade0de0', 'edfd8597-c616-5170-8a22-9ea0c3e26514', 'Under standard Lockout/Tagout (LOTO) protocols for isolating an electrical panel, which TWO of the following actions are strictly mandatory for the individual electrical worker performing the task?', '[{"id": "a", "text": "Applying a personal isolation lock under their sole control"}, {"id": "b", "text": "Placing a generic warning sign at the site entrance"}, {"id": "c", "text": "Attaching a personal danger tag identifying the worker and the date"}, {"id": "d", "text": "Removing the main utility supply fuses from the street pole"}, {"id": "e", "text": "Short-circuiting the active and neutral conductors together to prevent enlivening"}]', '["a", "c"]', 'VERIFIED. Safe working practices dictate that isolation must involve a personal lock (sole control) and a uniquely identifiable tag.', NULL, 3, NULL, '2026-05-12 13:49:54.773386+00', 'multiple_select');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('26100d57-8362-569d-bc8e-0864ea300603', '32b93254-79c6-5d4d-b9b1-ca2e1fa2a440', 'According to AS/NZS 3000, which TWO of the following methods are formally recognized as providing ''Additional Protection'' against direct contact in a low-voltage installation?', '[{"id": "a", "text": "Installing a Type A Residual Current Device (RCD) with a rated operating current not exceeding 30mA"}, {"id": "b", "text": "Utilizing a Separated Extra-Low Voltage (SELV) supply system"}, {"id": "c", "text": "Installing High Rupturing Capacity (HRC) fuses in the main switchboard"}, {"id": "d", "text": "Increasing the cross-sectional area of the main earthing conductor"}, {"id": "e", "text": "Applying heat-shrink tubing over the outer sheath of TPS cables"}]', '["a", "b"]', 'VERIFIED. Clause 2.4.3 explicitly lists ≤30mA RCDs and Extra-Low Voltage (SELV/PELV) systems as the approved methods for ''Additional Protection'' (life-saving back-up protection).', NULL, 3, NULL, '2026-05-12 13:49:54.773386+00', 'multiple_select');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('e62e8677-b54c-54a9-9000-de9c547dc196', 'cf002c8c-36ac-50c7-a590-36ab31e09e40', 'When utilizing the AS/NZS 3008 tables to determine the appropriate cable size for a circuit, what effect does an elevated ambient operating temperature (e.g., 50°C instead of the standard 40°C) have on the cable''s specifications?', '[{"id": "a", "text": "It decreases the current-carrying capacity (ampacity) of the cable, requiring a derating factor to be applied"}, {"id": "b", "text": "It increases the maximum permitted voltage drop limit for the installation from 5% to 7%"}, {"id": "c", "text": "It decreases the physical resistance of the copper conductors, allowing more current to flow safely"}, {"id": "d", "text": "It necessitates the installation of an active cooling fan within the conduit"}]', '["a"]', 'VERIFIED. Increased ambient temperature limits the cable''s ability to dissipate its own I^2R heat losses, thereby reducing its safe current-carrying capacity.', NULL, 3, NULL, '2026-05-12 13:49:54.773386+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('4f764770-c047-5954-8008-f6e8a8d87797', '08a18891-41e0-5ebe-86d4-86aecf47cf61', 'During a mandatory 500V DC insulation resistance test on a domestic installation, what is the required position of all two-way intermediate lighting switches to ensure a comprehensive and valid test?', '[{"id": "a", "text": "The test must be performed, the switches toggled to their alternate positions, and the test repeated to capture all strapper wires"}, {"id": "b", "text": "The switches must be left exactly as found; the test voltage will automatically bridge the contacts"}, {"id": "c", "text": "They must be completely disconnected from the circuit prior to applying the 500V DC test voltage"}, {"id": "d", "text": "They must be placed in the halfway (floating) position to isolate the load from the supply"}]', '["a"]', 'VERIFIED. Because multi-way switching alternates the active path between different ''strapper'' conductors, testing must be performed in both switch positions to ensure all copper paths are proven safe against earth.', NULL, 3, NULL, '2026-05-12 13:49:54.773386+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('e0c1c051-4af6-5ecd-b11c-070bb267e085', 'cd6d17a6-eac4-54af-a1b2-c443e9b8523b', 'What is the primary technical reason that the Earth Fault Loop Impedance (Zs) test must only be conducted on an energized (''live'') circuit?', '[{"id": "a", "text": "It requires the actual supply voltage to drive a test current through the complete earth return path back to the supply transformer"}, {"id": "b", "text": "The test instrument requires 230V AC simply to power its internal LCD screen"}, {"id": "c", "text": "The test artificially triggers the upstream MCB to record its mechanical disconnection speed"}, {"id": "d", "text": "It uses the live alternating current to permanently magnetize the copper earthing conductors"}]', '["a"]', 'VERIFIED. Zs verification is a live test because it measures the true impedance of the entire loop (including the street utility lines and transformer windings) by temporarily sinking a fault current to earth.', NULL, 3, NULL, '2026-05-12 13:49:54.773386+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('c4db3ff5-d5f4-5dcd-a23d-c5d73406ad1a', '33c66c01-f417-510d-be43-101e18e33a5d', 'Under the New Zealand Electricity (Safety) Regulations 2010, which document must be issued when prescribed electrical work involves the installation of a new main earthing system?', '[{"id": "a", "text": "A Certificate of Compliance (CoC) and an Electrical Safety Certificate (ESC)"}, {"id": "b", "text": "An Electrical Safety Certificate (ESC) only"}, {"id": "c", "text": "A Record of Inspection (RoI) only"}, {"id": "d", "text": "No certification is required for earthing upgrades"}]', '["a"]', 'VERIFIED. Installing a main earthing system is classified as high-risk/complex PEW, strictly requiring both a CoC (certifying the design/build) and an ESC (certifying the testing).', NULL, 3, NULL, '2026-05-12 13:49:54.773386+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('a6c13a51-d350-5ca3-886f-86ee374676a2', '4b09cc13-dedd-58f5-880c-9d460f74562e', 'In a three-phase Delta-connected AC motor, what is the mathematical relationship between the Line Voltage (V_L) and the Phase Voltage (V_P)?', '[{"id": "a", "text": "Line Voltage is exactly equal to Phase Voltage (V_L = V_P)"}, {"id": "b", "text": "Line Voltage is equal to Phase Voltage multiplied by the square root of 3 (V_L = √3 x V_P)"}, {"id": "c", "text": "Line Voltage is exactly half of the Phase Voltage (V_L = V_P / 2)"}, {"id": "d", "text": "Line Voltage lags Phase Voltage by 30 degrees"}]', '["a"]', 'VERIFIED. AC Theory fundamental: In a Delta configuration, Line Voltage = Phase Voltage, but Line Current = Phase Current x √3. (In Star, it is the exact opposite).', NULL, 3, NULL, '2026-05-12 13:49:54.773386+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('fc1f3d31-5ee8-533f-b549-9e98b75a852e', 'ac388207-779c-5a46-a6e9-b556f0578f56', 'When designing a final subcircuit for a fixed space heater in a domestic living room, AS/NZS 3000 requires the switch controlling the heater to be installed where in relation to the appliance?', '[{"id": "a", "text": "In the same room as the heater and readily accessible"}, {"id": "b", "text": "Mounted directly on the main switchboard to restrict unauthorized use"}, {"id": "c", "text": "Outside the living room to prevent thermal damage to the switch mechanism"}, {"id": "d", "text": "At a minimum height of 2.0m above the floor"}]', '["a"]', 'VERIFIED. Clause 4.12 requires the functional switch for a fixed space heater to be readily accessible and situated in the same room to allow immediate control in case of malfunction or emergency.', NULL, 3, NULL, '2026-05-12 13:49:54.773386+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('d49d1d91-7cf9-508a-83b8-e6ba7c7f2bd2', 'cf002c8c-36ac-50c7-a590-36ab31e09e40', 'A 20A single-phase final subcircuit is wired using a cable with a voltage drop constant (Vc) of 15.6 mV/A.m. If the total route length of the cable is 40 metres, calculate the total voltage drop for this circuit in Volts. Provide your exact answer.', NULL, '{"unit": "V", "answers": ["12.48", "12.5"], "tolerance": 0.05}', 'VERIFIED. Vd = (L x I x Vc) / 1000. Vd = (40m x 20A x 15.6) / 1000. Vd = 12480 / 1000 = 12.48V.', NULL, 3, NULL, '2026-05-12 13:49:54.773386+00', 'exact_value');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('4018b2d5-7ff3-55fd-bbf8-5c3e59ba5ef4', '4485a268-25ec-58de-8df8-5fa3df330063', 'Under AS/NZS 3000, which TWO of the following statements regarding the Multiple Earthed Neutral (MEN) link are strictly correct?', '[{"id": "a", "text": "It must physically connect the main earth busbar to the main neutral busbar"}, {"id": "b", "text": "It must be located exclusively on the main switchboard of the installation"}, {"id": "c", "text": "It must incorporate a high-rupturing capacity (HRC) fuse for overload protection"}, {"id": "d", "text": "It is only required in installations utilizing a TT earthing system"}, {"id": "e", "text": "It must be completely insulated with green and yellow heat-shrink tubing"}]', '["a", "b"]', 'VERIFIED. The MEN link''s sole purpose is to bond the neutral and earth bars together at the main switchboard to provide a low-impedance fault return path. It must NEVER be fused or switched.', NULL, 3, NULL, '2026-05-12 13:49:54.773386+00', 'multiple_select');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('c7272969-c47e-5879-91ed-a70cf40b7a2a', '33c66c01-f417-510d-be43-101e18e33a5d', 'Under the New Zealand Electricity (Safety) Regulations 2010 (ECP 51), which TWO of the following tasks are legally permitted to be carried out by a homeowner in their own primary residence without holding an electrical registration?', '[{"id": "a", "text": "Replacing a damaged socket-outlet with an identical new socket-outlet"}, {"id": "b", "text": "Replacing an existing incandescent light fitting with an identical fitting"}, {"id": "c", "text": "Installing a new circuit breaker on the main switchboard"}, {"id": "d", "text": "Running a new TPS cable through the wall to install an additional power point"}, {"id": "e", "text": "Upgrading the main earthing lead to the street water pipe"}]', '["a", "b"]', 'VERIFIED. Homeowners are strictly limited to ''like-for-like'' replacement of basic fittings. Altering switchboards or installing new fixed wiring requires a registered electrical worker.', NULL, 3, NULL, '2026-05-12 13:49:54.773386+00', 'multiple_select');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('01740355-3f28-5a94-b1ff-9d8b05aad91c', '4b09cc13-dedd-58f5-880c-9d460f74562e', 'A single-phase ideal step-down transformer is connected to a 230V AC primary supply and produces a 24V AC secondary output. If the primary coil contains 1,150 turns of wire, how many turns of wire must be on the secondary coil?', NULL, '{"unit": "turns", "answers": ["120"], "tolerance": 0.0}', 'VERIFIED. Turns ratio formula: Np/Ns = Vp/Vs. Therefore, 1150/Ns = 230/24. Cross-multiplying gives 230 * Ns = 27600. Ns = 27600 / 230 = 120 turns.', NULL, 3, NULL, '2026-05-12 13:49:54.773386+00', 'exact_value');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('03861ba5-78cb-59e0-b128-cae9dc7516bd', '4a54f2ca-b514-539b-b086-a779d234b99f', 'According to AS/NZS 3000, what is the maximum permitted tripping time for a standard 30mA Type A Residual Current Device (RCD) when subjected to a fault current exactly equal to its rated residual operating current (1 x IΔn)?', '[{"id": "a", "text": "300 milliseconds (0.3s)"}, {"id": "b", "text": "40 milliseconds (0.04s)"}, {"id": "c", "text": "400 milliseconds (0.4s)"}, {"id": "d", "text": "1000 milliseconds (1.0s)"}]', '["a"]', 'VERIFIED. Under standard RCD testing parameters, a device tested at 1x its rated fault current (30mA) must trip within 300ms. (Testing at 5x requires a 40ms trip time).', NULL, 3, NULL, '2026-05-12 13:49:54.773386+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('d00836a7-de03-53c6-8989-faf4ac6f5ca8', '1b3cf5db-12ef-59aa-9127-e3d6dcb35a2f', 'In a medical facility, a specific room is designated as a ''Body-Protected'' patient area. Under AS/NZS 3003, what is the required rating and classification for the RCDs protecting the medical socket-outlets in this room?', '[{"id": "a", "text": "10mA, Type 1"}, {"id": "b", "text": "30mA, Type A"}, {"id": "c", "text": "100mA, Type S"}, {"id": "d", "text": "30mA, Type AC"}]', '["a"]', 'VERIFIED. Because patient skin resistance may be bypassed during treatment, AS/NZS 3003 strictly mandates highly sensitive 10mA Type 1 RCDs for Body-Protected areas to prevent micro-shock electrocution.', NULL, 3, NULL, '2026-05-12 13:49:54.773386+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('dce1c640-03fd-58f7-98fb-e5cd5cfb9c94', '647fd115-7e2c-5505-9d7c-bc0583d79045', 'When a three-phase induction motor is started Direct-On-Line (DOL), the initial starting current (inrush) is typically how many times greater than the motor''s full-load running current (FLC)?', '[{"id": "a", "text": "6 to 8 times the FLC"}, {"id": "b", "text": "2 to 3 times the FLC"}, {"id": "c", "text": "10 to 12 times the FLC"}, {"id": "d", "text": "It is exactly equal to the FLC"}]', '["a"]', 'VERIFIED. Motor theory standard: Without a soft starter or star-delta reduction, a stationary motor acts almost like a short circuit, drawing massive inrush current (typically 600% to 800%) until the rotor builds magnetic back-EMF.', NULL, 3, NULL, '2026-05-12 13:49:54.773386+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('30dc81da-6be7-5bd7-88fc-1b2ec3f150a9', 'cd6d17a6-eac4-54af-a1b2-c443e9b8523b', 'According to AS/NZS 3000 Clause 8.2, a comprehensive visual inspection must be carried out before any electrical testing begins. Which TWO of the following items are legally required to be visually verified during this inspection?', '[{"id": "a", "text": "That equipment is protected against direct contact with live parts (e.g., enclosures and insulation are intact)"}, {"id": "b", "text": "That the conductors selected are of the correct cross-sectional area for the load and voltage drop"}, {"id": "c", "text": "That the actual earth fault loop impedance value is below 1 Ohm"}, {"id": "d", "text": "That the exact phase angle of the supply transformer matches the local grid"}, {"id": "e", "text": "That the internal harmonic distortion of the local WiFi router is within limits"}]', '["a", "b"]', 'VERIFIED. Visual inspections (Clause 8.2) involve checking what can be seen: proper insulation/enclosures (direct contact protection) and ensuring the correct size cables were physically installed. Loop impedance and phase angles require instrument testing, not visual inspection.', NULL, 3, NULL, '2026-05-12 13:49:54.773386+00', 'multiple_select');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('df8647ed-5410-55ef-907b-7558470a327e', '72860a92-1d9b-550e-b0f8-648c5100c321', 'According to the location restrictions in AS/NZS 3000, which TWO of the following environments are strictly prohibited for the installation of a main switchboard?', '[{"id": "a", "text": "Directly above any fixed domestic cooking appliance"}, {"id": "b", "text": "Within any designated zone (0, 1, or 2) of a damp situation such as a bathroom"}, {"id": "c", "text": "In a residential hallway with a 1.0-metre clear working space"}, {"id": "d", "text": "Inside an attached, enclosed residential garage"}, {"id": "e", "text": "On an exterior wall housed within a weatherproof enclosure"}]', '["a", "b"]', 'VERIFIED. Clause 2.9.2.5 expressly prohibits switchboards over cooking appliances (fire/heat hazard) and within the classified zones of damp situations (moisture/shock hazard).', NULL, 3, NULL, '2026-05-12 13:49:54.773386+00', 'multiple_select');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('fa9b8e36-fa5d-5e24-9e0d-bd0138b7d7e2', '061d9060-cc7d-5338-a541-044dce012e11', 'A 230V lighting circuit is protected by a 16A Type B Miniature Circuit Breaker (MCB). Assuming the magnetic trip multiplier for a Type B device is 4.0x the rated current to ensure instantaneous operation, calculate the maximum permissible Earth Fault Loop Impedance (Zs) in Ohms. Provide your answer to two decimal places.', NULL, '{"unit": "Ω", "answers": ["3.59"], "tolerance": 0.05}', 'VERIFIED. Tripping current (Ia) = 16A x 4.0 = 64A. Loop Impedance (Zs) = Uo / Ia. Zs = 230V / 64A = 3.59375 ohms. Rounds to 3.59 ohms.', NULL, 3, NULL, '2026-05-12 13:49:54.773386+00', 'exact_value');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('534fae19-f117-5e79-a649-cfdb7dd20f4d', '32b93254-79c6-5d4d-b9b1-ca2e1fa2a440', 'When a standard thermoplastic sheathed (TPS) cable is installed in a ceiling space and is completely surrounded by bulk thermal insulation for a distance exceeding 400mm, what is the approximate derating effect on the cable''s current-carrying capacity?', '[{"id": "a", "text": "Its current-carrying capacity is reduced by approximately 50%"}, {"id": "b", "text": "Its current-carrying capacity is reduced by exactly 10%"}, {"id": "c", "text": "Its voltage drop limit is halved to 2.5%"}, {"id": "d", "text": "It requires an immediate upgrade to a high-temperature silicone cable"}]', '["a"]', 'VERIFIED. Under AS/NZS 3008, a cable completely surrounded by thermal insulation for more than 400mm loses its ability to dissipate heat, requiring a derating factor of 0.5 (halving its safe ampacity) to prevent the PVC insulation from melting.', NULL, 3, NULL, '2026-05-12 13:49:54.773386+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('f81861af-e1b0-5480-a3ab-ce011f83b140', '0a093bc7-b34e-561b-87be-c1acae0e9fc0', 'A recessed LED downlight carries the official classification ''IC-4''. What does this specific thermal classification indicate under AS/NZS 3000?', '[{"id": "a", "text": "The luminaire can be safely abutted by and completely covered with bulk thermal insulation without causing a fire hazard"}, {"id": "b", "text": "The luminaire must maintain a strict 40mm physical clearance from all structural timber"}, {"id": "c", "text": "The luminaire is exclusively rated for use in Zone 0 damp situations"}, {"id": "d", "text": "The luminaire requires a dedicated 4-amp protective device"}]', '["a"]', 'VERIFIED. ''IC'' stands for Insulation Contact. The IC-4 classification (common in AS/NZS) means the fitting is designed to be fully covered by building insulation without overheating.', NULL, 3, NULL, '2026-05-12 13:49:54.773386+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('a42ac931-8f8e-5b60-986d-43ecafdbcf58', 'cd6d17a6-eac4-54af-a1b2-c443e9b8523b', 'According to the mandatory testing sequence in AS/NZS 3000 Chapter 8, which TWO of the following tests must strictly be conducted on a ''dead'' (de-energized) installation?', '[{"id": "a", "text": "Earth Continuity"}, {"id": "b", "text": "Insulation Resistance"}, {"id": "c", "text": "Earth Fault Loop Impedance (Zs)"}, {"id": "d", "text": "RCD Trip Time Verification"}, {"id": "e", "text": "Phase Sequence"}]', '["a", "b"]', 'VERIFIED. Earth continuity and Insulation resistance are measured using low-voltage internal batteries and 500V DC megger pulses, respectively. Applying these instruments to a live circuit will destroy the tester and pose a severe shock hazard. Loop impedance, RCD timing, and phase sequence require active mains voltage.', NULL, 3, NULL, '2026-05-12 13:49:54.773386+00', 'multiple_select');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('2559d1e7-d2f4-5ab2-8f4d-b1d67b040666', '1b3cf5db-12ef-59aa-9127-e3d6dcb35a2f', 'When a grid-tied Solar Photovoltaic (PV) system is installed on a domestic premises, AS/NZS 4777 dictates that a specific warning label must be applied to the main switchboard. What is the primary purpose of this label?', '[{"id": "a", "text": "To warn workers that the installation has multiple active power supplies and both the grid and the inverter must be isolated before commencing work"}, {"id": "b", "text": "To indicate the exact DC voltage generated by the roof panels"}, {"id": "c", "text": "To certify that the inverter complies with radio frequency interference limits"}, {"id": "d", "text": "To warn that the property owner is selling power back to the local utility grid"}]', '["a"]', 'VERIFIED. The dual-supply warning is a critical life-safety requirement. Turning off the main switch does not de-energize the solar side of the board; workers must isolate the grid AND the solar inverter to achieve total dead state.', NULL, 3, NULL, '2026-05-12 13:49:54.773386+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('e66b873f-c7dd-5aa1-868e-4a9081f671ce', '647fd115-7e2c-5505-9d7c-bc0583d79045', 'If a three-phase induction motor loses one of its supply phases while running under normal load (a fault known as ''single-phasing''), what is the immediate electrical consequence?', '[{"id": "a", "text": "The motor will continue to run, but the current in the remaining two phases will dramatically increase, causing severe overheating"}, {"id": "b", "text": "The motor will instantly stop and physically lock its rotor in place"}, {"id": "c", "text": "The motor will instantly reverse its direction of rotation"}, {"id": "d", "text": "The motor will continue to run perfectly normally with a proportionally reduced power output"}]', '["a"]', 'VERIFIED. Single-phasing forces the remaining two phases to carry the entire mechanical load. This draws excessive current, rapidly burning out the stator windings unless a thermal overload relay detects the imbalance and trips.', NULL, 3, NULL, '2026-05-12 13:49:54.773386+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('bc890f78-e738-5073-95df-9439ab78af4e', '4b09cc13-dedd-58f5-880c-9d460f74562e', 'In an alternating current (AC) system, the ''period'' (T) is the time it takes for one complete cycle of the waveform to occur. If the period of a supply waveform is exactly 0.02 seconds (20 milliseconds), calculate the frequency of the supply in Hertz (Hz).', NULL, '{"unit": "Hz", "answers": ["50"], "tolerance": 0.0}', 'VERIFIED. Frequency (f) = 1 / Period (T). f = 1 / 0.02 = 50. The standard mains frequency in New Zealand is 50Hz.', NULL, 3, NULL, '2026-05-12 13:49:54.773386+00', 'exact_value');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('ca0f5352-3211-5e45-9369-190996b994b9', '33c66c01-f417-510d-be43-101e18e33a5d', 'Under the New Zealand Electricity (Safety) Regulations 2010, which TWO of the following tasks are legally classified as ''High-Risk'' Prescribed Electrical Work (PEW) requiring a Record of Inspection (RoI) from a registered Electrical Inspector?', '[{"id": "a", "text": "Installing a new main earthing system"}, {"id": "b", "text": "Installing new consumer mains cables from the point of supply to the main switchboard"}, {"id": "c", "text": "Replacing an existing 20A MCB with a new 20A MCB on a domestic distribution board"}, {"id": "d", "text": "Installing an additional double socket-outlet on an existing final subcircuit"}, {"id": "e", "text": "Replacing a faulty heating element in a domestic hot water cylinder"}]', '["a", "b"]', 'VERIFIED. ESR 2010 Part 5 strictly designates work on mains, main earthing systems, medical areas, hazardous areas, and mains-parallel generation (solar) as high-risk, mandating independent third-party inspection.', NULL, 3, NULL, '2026-05-12 13:49:54.773386+00', 'multiple_select');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('8384b98b-805a-5224-ad10-22a67e4524b5', 'cf002c8c-36ac-50c7-a590-36ab31e09e40', 'A 32A single-phase final subcircuit is wired using a cable with a specified voltage drop constant (Vc) of 4.8 mV/A.m. If the physical route length of the cable is 25 metres, calculate the total voltage drop for this circuit in Volts. Provide your exact answer.', NULL, '{"unit": "V", "answers": ["3.84"], "tolerance": 0.05}', 'VERIFIED. The voltage drop formula is Vd = (L x I x Vc) / 1000. Vd = (25m x 32A x 4.8) / 1000. Vd = 3840 / 1000 = 3.84 Volts.', NULL, 3, NULL, '2026-05-12 13:49:54.773386+00', 'exact_value');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('dfd4f500-7a46-50b7-a002-94ce3be82b33', 'edfd8597-c616-5170-8a22-9ea0c3e26514', 'Under AS/NZS 4836 (Safe working on or near low-voltage electrical installations), when performing live fault finding on an energized main switchboard with a high prospective fault current, which TWO of the following items of Personal Protective Equipment (PPE) are strictly required as a minimum?', '[{"id": "a", "text": "Safety glasses or a full arc-rated face shield"}, {"id": "b", "text": "Voltage-rated insulating gloves"}, {"id": "c", "text": "A high-visibility nylon safety vest"}, {"id": "d", "text": "Steel-capped boots with electrically conductive soles"}, {"id": "e", "text": "A standard P2 particulate dust mask"}]', '["a", "b"]', 'VERIFIED. AS/NZS 4836 mandates protection against both electric shock and arc flash. Voltage-rated gloves prevent shock, while face shields/safety glasses protect against the blinding light and flying debris of an arc flash. Nylon clothing and conductive boots are strictly prohibited.', NULL, 3, NULL, '2026-05-12 13:49:54.773386+00', 'multiple_select');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('b05e0f64-98d5-5a31-a59a-eb9aa7ab1e61', '08a18891-41e0-5ebe-86d4-86aecf47cf61', 'When performing a 500V DC Insulation Resistance (megger) test on a main switchboard, how must Surge Protective Devices (SPDs) be handled to ensure an accurate test and prevent equipment damage?', '[{"id": "a", "text": "They must be disconnected or completely isolated during the test, as the 500V test voltage may cause them to safely conduct to earth, registering a false fail"}, {"id": "b", "text": "They must be left securely connected to actively protect the switchboard from the megger''s high-voltage testing pulse"}, {"id": "c", "text": "They must be temporarily bridged out with a heavy copper link to ensure continuity"}, {"id": "d", "text": "Their local earth connection must be upgraded to a minimum of 16mm² prior to the test"}]', '["a"]', 'VERIFIED. Surge arrestors are designed to dump high voltages (like a 500V DC test pulse) to earth. If left connected during an IR test, they will function exactly as designed, resulting in a false 0 MΩ (short circuit) reading.', NULL, 3, NULL, '2026-05-12 13:49:54.773386+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('2a9c6231-acab-542b-8871-89fbb3f1f145', 'ac388207-779c-5a46-a6e9-b556f0578f56', 'According to AS/NZS 3000 Clause 4.3.2, what is a specific clearance requirement for a standard double socket-outlet installed near a domestic gas cooktop?', '[{"id": "a", "text": "It must not be installed within 150mm of the edge of the nearest gas burner"}, {"id": "b", "text": "It must be installed exactly 50mm below the physical surface level of the cooktop"}, {"id": "c", "text": "It must be installed at least 1.0 metre horizontally from any flexible gas connection"}, {"id": "d", "text": "Socket-outlets are strictly prohibited from being installed in the same room as a flueless gas appliance"}]', '["a"]', 'VERIFIED. To prevent heat damage to the PVC faceplate and flexible appliance cords, AS/NZS 3000 dictates a 150mm exclusion zone radiating from the edge of any gas or electric cooking burner element.', NULL, 3, NULL, '2026-05-12 13:49:54.773386+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('f747a3b5-fd28-5b6f-b133-35bb7087ca02', '4485a268-25ec-58de-8df8-5fa3df330063', 'In a standard New Zealand TN-C-S electrical distribution system, at what specific point is the combined utility Protective Earth and Neutral (PEN) conductor formally separated into dedicated, individual earth and neutral conductors for the consumer?', '[{"id": "a", "text": "At the main switchboard of the installation via the Multiple Earthed Neutral (MEN) link"}, {"id": "b", "text": "At the point of attachment on the exterior roof fascia"}, {"id": "c", "text": "Inside the utility-owned street distribution transformer"}, {"id": "d", "text": "Within each individual final subcircuit socket-outlet"}]', '["a"]', 'VERIFIED. In a TN-C-S (Terra Neutral - Combined - Separated) system, the street mains combine Earth and Neutral into a single PEN wire. At the consumer''s main switchboard, the MEN link officially ''Separates'' them into the distinct Earth bar and Neutral bar.', NULL, 3, NULL, '2026-05-12 13:49:54.773386+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('bbdeae9d-69d3-5a48-a03d-0858918bd94b', 'cd6d17a6-eac4-54af-a1b2-c443e9b8523b', 'During a routine Earth Fault Loop Impedance (Zs) test, the measured reading is dangerously close to the maximum permissible limit. Which TWO of the following physical factors directly contribute to a higher (worse) Zs reading?', '[{"id": "a", "text": "A loose, oxidized, or corroded connection at the Multiple Earthed Neutral (MEN) link"}, {"id": "b", "text": "An excessively long final subcircuit cable run"}, {"id": "c", "text": "Utilizing a cable with a cross-sectional area (CSA) that is much larger than necessary"}, {"id": "d", "text": "The protective Miniature Circuit Breaker (MCB) being rated too high for the load"}, {"id": "e", "text": "Installing a highly sensitive 10mA RCD instead of a standard 30mA RCD"}]', '["a", "b"]', 'VERIFIED. Zs is purely a measurement of electrical resistance/impedance. Loose connections add physical resistance. Longer cables add physical resistance. (Larger cables *lower* resistance, and the rating of the breaker/RCD has no physical effect on the copper''s impedance).', NULL, 3, NULL, '2026-05-12 13:49:54.773386+00', 'multiple_select');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('8dbcb4ae-f641-5951-b297-09bf1e1b5f62', '33c66c01-f417-510d-be43-101e18e33a5d', 'Under the EWRB supervision guidelines and the Electricity Act 1992, which scenario accurately describes the minimum requirement for ''Direct Supervision'' of an unlicensed electrical apprentice carrying out Prescribed Electrical Work (PEW)?', '[{"id": "a", "text": "The registered supervisor is physically present on the same site, actively observing the work, and is immediately available to intervene if required"}, {"id": "b", "text": "The registered supervisor issues verbal instructions over the phone and returns to inspect the work the following day"}, {"id": "c", "text": "The registered supervisor provides a detailed, approved written wiring diagram before leaving the apprentice alone on site"}, {"id": "d", "text": "The registered supervisor reviews the final testing results after the apprentice has energized the completed circuit"}]', '["a"]', 'VERIFIED. Direct supervision legally mandates physical presence. The supervisor must be close enough to take immediate physical control of the situation to prevent injury or unsafe work practices.', NULL, 3, NULL, '2026-05-12 13:49:54.773386+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('a1a36cf9-0b59-579b-95f8-e8f5ea01fcc4', '4b09cc13-dedd-58f5-880c-9d460f74562e', 'In a commercial alternating current (AC) installation, what is the primary negative consequence of operating a network with a significantly poor (low) power factor?', '[{"id": "a", "text": "The installation must draw a much higher total current (Apparent Power) from the utility supply to perform the exact same amount of useful work (True Power)"}, {"id": "b", "text": "The supply voltage automatically increases to dangerous levels, risking immediate insulation breakdown"}, {"id": "c", "text": "The frequency of the supply grid fluctuates wildly, causing three-phase synchronous motors to stall"}, {"id": "d", "text": "The real power (kW) consumed by the mechanical load mathematically doubles"}]', '["a"]', 'VERIFIED. A low power factor means excessive Reactive Power is bouncing back and forth on the lines. This forces the cables and transformers to carry higher current (kVA) just to deliver the required True Power (kW), resulting in overloaded cables and higher utility penalties.', NULL, 3, NULL, '2026-05-12 13:49:54.773386+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('b62d4492-d647-5f94-a6e4-214afda3633b', '061d9060-cc7d-5338-a541-044dce012e11', 'A 230V commercial final subcircuit is protected by a 40A HRC fuse. According to the manufacturer''s time/current curves, this specific fuse requires exactly 250A of fault current to blow and disconnect the circuit within the mandated 0.4 seconds. Calculate the absolute maximum permissible Earth Fault Loop Impedance (Zs) in Ohms. Provide your answer to two decimal places.', NULL, '{"unit": "Ω", "answers": ["0.92"], "tolerance": 0.02}', 'VERIFIED. Ohm''s law strictly applies to fault loops. Z = V / I. Zs = 230V / 250A = 0.92 Ohms. If the impedance exceeds 0.92Ω, the fault current will fall below 250A, and the fuse will not blow fast enough to save a life.', NULL, 3, NULL, '2026-05-12 13:49:54.773386+00', 'exact_value');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('ae1bfa59-1528-5f5d-9845-95ea6e837427', '1b3cf5db-12ef-59aa-9127-e3d6dcb35a2f', 'When installing electrical equipment in a highly explosive hazardous area (such as a Zone 0 petrochemical tank), equipment marked with the protection technique ''Ex i'' is often mandated. What does the classification ''Ex i'' specifically indicate?', '[{"id": "a", "text": "Intrinsic Safety: The electrical energy available within the circuit is strictly limited to a level so low that it cannot physically ignite the explosive atmosphere, even under fault conditions"}, {"id": "b", "text": "Increased Safety: The equipment enclosure is hermetically sealed and pressurized to prevent any explosive gas from entering the housing"}, {"id": "c", "text": "Flameproof Enclosure: The equipment is highly robust and designed to safely contain an internal electrical explosion without igniting the outside atmosphere"}, {"id": "d", "text": "Oil Immersion: The live electrical contacts are entirely submerged in a non-conductive dielectric oil bath"}]', '["a"]', 'VERIFIED. ''Ex i'' (Intrinsic Safety) is a foundational concept for hazardous areas. Instead of trying to contain an explosion (Flameproof ''Ex d''), intrinsically safe circuits simply do not possess enough thermal or electrical energy (sparks) to start a fire in the first place.', NULL, 3, NULL, '2026-05-12 13:49:54.773386+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('0d24b863-072f-5cbd-b061-ff1e28a58ba0', 'cf002c8c-36ac-50c7-a590-36ab31e09e40', 'A 40A three-phase final subcircuit is wired using a cable with a designated three-phase voltage drop constant (Vc) of 3.2 mV/A.m. The physical route length of the cable is exactly 50 metres. Calculate the total voltage drop for this circuit in Volts. Provide your exact answer.', NULL, '{"unit": "V", "answers": ["6.4", "6.40"], "tolerance": 0.05}', 'VERIFIED. The voltage drop formula is Vd = (L x I x Vc) / 1000. Vd = (50m x 40A x 3.2) / 1000. Vd = 6400 / 1000 = 6.4 Volts.', NULL, 3, NULL, '2026-05-12 13:49:54.773386+00', 'exact_value');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('b17cf564-4f63-5d94-9290-b34aaf1f813f', '647fd115-7e2c-5505-9d7c-bc0583d79045', 'Which TWO of the following statements correctly describe the electrical operation and physical characteristics of a Star-Delta motor starter?', '[{"id": "a", "text": "It reduces the starting line current to approximately one-third (1/3) of the Direct-On-Line (DOL) current"}, {"id": "b", "text": "It requires the motor''s terminal box to have only three accessible connecting terminals"}, {"id": "c", "text": "The motor must be specifically designed to run continuously in the Delta configuration at the nominal supply voltage"}, {"id": "d", "text": "It utilizes an internal microprocessor to actively alter the supply frequency (Hz) for a smooth speed ramp"}, {"id": "e", "text": "It physically triples the mechanical starting torque compared to a DOL start"}]', '["a", "c"]', 'VERIFIED. A Star-Delta starter mechanically links the windings in Star for startup (reducing voltage per winding, slashing inrush current to 1/3, and slashing torque to 1/3) before switching to Delta for full-power running. It requires a 6-terminal motor.', NULL, 3, NULL, '2026-05-12 13:49:54.773386+00', 'multiple_select');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('10aa8a28-781f-5744-8952-34ca8003027f', 'cd6d17a6-eac4-54af-a1b2-c443e9b8523b', 'During dead testing of a final subcircuit, an electrical worker measures the phase conductor resistance (R1) as 0.15 Ohms and the protective earth conductor resistance (R2) as 0.20 Ohms. If the external earth fault loop impedance (Ze) measured independently at the main switchboard is 0.45 Ohms, calculate the total Earth Fault Loop Impedance (Zs) for this circuit in Ohms.', NULL, '{"unit": "Ω", "answers": ["0.80", "0.8"], "tolerance": 0.01}', 'VERIFIED. The formula for total loop impedance is Zs = Ze + R1 + R2. Zs = 0.45 + 0.15 + 0.20 = 0.80 Ohms.', NULL, 3, NULL, '2026-05-12 13:49:54.773386+00', 'exact_value');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('3d174678-7dff-5778-af5b-f1f54deaf7b1', '0a093bc7-b34e-561b-87be-c1acae0e9fc0', 'According to AS/NZS 3000 Clause 4.8.2, which TWO of the following are mandatory physical requirements for an isolating switch controlling a fixed electric storage water heater?', '[{"id": "a", "text": "It must be installed directly adjacent to the water heater"}, {"id": "b", "text": "It must physically break and disconnect all active conductors"}, {"id": "c", "text": "It must be located exclusively on the main switchboard to restrict homeowner access"}, {"id": "d", "text": "It must possess a minimum current rating of 32A, regardless of the heating element''s actual size"}, {"id": "e", "text": "It must automatically disconnect the supply if an internal water leak is detected"}]', '["a", "b"]', 'VERIFIED. Clause 4.8.2 requires water heaters to have a dedicated isolation switch installed adjacent to the appliance (allowing the plumber/sparky to visually guarantee the power is off while working), and it must isolate all active conductors.', NULL, 3, NULL, '2026-05-12 13:49:54.773386+00', 'multiple_select');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('22c77e07-1227-54c7-b7bb-a2e5d6d0480b', 'edfd8597-c616-5170-8a22-9ea0c3e26514', 'According to current New Zealand Resuscitation Council guidelines, what is the correct mandated ratio of chest compressions to rescue breaths when performing CPR on an adult victim of electric shock?', '[{"id": "a", "text": "30 compressions to 2 breaths"}, {"id": "b", "text": "15 compressions to 2 breaths"}, {"id": "c", "text": "50 compressions to 5 breaths"}, {"id": "d", "text": "5 compressions to 1 breath"}]', '["a"]', 'VERIFIED. The standard basic life support (BLS) protocol in New Zealand for adults is to push hard and fast at a ratio of 30 chest compressions followed by 2 rescue breaths (30:2).', NULL, 3, NULL, '2026-05-12 13:49:54.773386+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('843914fb-4e9b-5ee4-a312-667d21230b82', '32b93254-79c6-5d4d-b9b1-ca2e1fa2a440', 'According to the internationally aligned recommendations in AS/NZS 3000 Table 3.4, what are the officially recommended core insulation colours for a three-phase alternating current supply (Phase 1, Phase 2, Phase 3, Neutral)?', '[{"id": "a", "text": "Brown, Black, Grey, Light Blue"}, {"id": "b", "text": "Red, Yellow, Blue, Black"}, {"id": "c", "text": "Red, White, Blue, Black"}, {"id": "d", "text": "Brown, Orange, Yellow, Green/Yellow"}]', '["a"]', 'VERIFIED. While Red/White/Blue for phases and Black for neutral is still legally permissible and widely installed, Table 3.4 designates the European harmonized colours (Brown/Black/Grey for Active, Light Blue for Neutral) as the ''recommended'' standard.', NULL, 3, NULL, '2026-05-12 13:49:54.773386+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('6e5d682b-c6fe-5f4f-8c10-9e5f48cc5ab9', '4b09cc13-dedd-58f5-880c-9d460f74562e', 'A single-phase electric motor draws an apparent power of 5.0 kVA from the AC grid supply, but due to its highly inductive nature, it only performs 4.0 kW of true useful work. Calculate the Power Factor of this motor. Provide your answer as a decimal.', NULL, '{"unit": "", "answers": ["0.8", "0.80"], "tolerance": 0.0}', 'VERIFIED. Power Factor is the ratio of True Power (kW) to Apparent Power (kVA). pf = kW / kVA = 4.0 / 5.0 = 0.8.', NULL, 3, NULL, '2026-05-12 13:49:54.773386+00', 'exact_value');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('718d412e-2786-5004-9448-33edc39a058e', '4a54f2ca-b514-539b-b086-a779d234b99f', 'When commissioning a new 30mA RCD to protect a final subcircuit, AS/NZS 3000 Chapter 8 mandates that the device must be verified using specialized RCD test equipment. Which functional parameter is strictly measured and recorded during this test?', '[{"id": "a", "text": "The exact time in milliseconds it takes for the RCD to disconnect the supply when subjected to a specific simulated fault current"}, {"id": "b", "text": "The maximum prospective short-circuit current the RCD''s internal contacts can withstand before failing"}, {"id": "c", "text": "The internal insulation resistance of the RCD''s magnetic core coil"}, {"id": "d", "text": "The exact temperature rise of the RCD housing when operating under a full continuous load"}]', '["a"]', 'VERIFIED. RCD verification involves injecting a known fault current (e.g., 30mA) and timing how fast the mechanical contacts break the circuit to ensure it meets the life-safety threshold (maximum 300ms).', NULL, 3, NULL, '2026-05-12 13:49:54.773386+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('c568068a-88b4-5836-83b8-46789d5cbd1d', '33c66c01-f417-510d-be43-101e18e33a5d', 'Under the Electricity (Safety) Regulations 2010, which TWO of the following conditions must be met for a person to legally sign and issue a Certificate of Compliance (CoC) for prescribed electrical work?', '[{"id": "a", "text": "The person must be a registered electrical worker holding a current practising licence appropriate for that specific type of work"}, {"id": "b", "text": "The person must have either carried out the physical work themselves or actively and directly supervised the work"}, {"id": "c", "text": "The person must hold a current EWRB Inspector registration"}, {"id": "d", "text": "The person must be a Chartered Professional Engineer (CPEng)"}, {"id": "e", "text": "The person must obtain written approval from the local network utility company prior to issuing the CoC"}]', '["a", "b"]', 'VERIFIED. Only a suitably registered and licensed electrical worker who actually did the work (or supervised the apprentice who did it) holds the legal authority and accountability to issue the CoC.', NULL, 3, NULL, '2026-05-12 13:49:54.773386+00', 'multiple_select');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('14285476-b270-5691-8619-11494114a938', '061d9060-cc7d-5338-a541-044dce012e11', 'A 230V final subcircuit is protected by a 50A Type D Miniature Circuit Breaker (MCB) supplying a large industrial welder. Assuming the magnetic trip multiplier for a Type D device is 12.5x the rated current to guarantee instantaneous tripping, calculate the maximum permissible Earth Fault Loop Impedance (Zs) in Ohms. Provide your answer to two decimal places.', NULL, '{"unit": "Ω", "answers": ["0.37", "0.36"], "tolerance": 0.01}', 'VERIFIED. Tripping current (Ia) = 50A x 12.5 = 625A. Loop Impedance (Zs) = Uo / Ia. Zs = 230V / 625A = 0.368 Ohms. Rounded to 0.37 Ohms. Note how incredibly low the impedance must be to clear a Type D breaker.', NULL, 3, NULL, '2026-05-12 13:49:54.773386+00', 'exact_value');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('a552451a-9324-5ec2-8fcd-37f181bdf0b3', 'cd6d17a6-eac4-54af-a1b2-c443e9b8523b', 'Under AS/NZS 3000 Chapter 8, when verifying the operation of a 30mA RCD using an active test instrument, which TWO of the following specific conditions must be met for the test to be legally considered a ''pass''?', '[{"id": "a", "text": "The RCD must disconnect the supply within 300 milliseconds when tested at its rated residual current (1 x IΔn)"}, {"id": "b", "text": "The RCD must trip instantly when tested at 10% of its rated residual current to prove sensitivity"}, {"id": "c", "text": "The test must be performed at both 0 degrees and 180 degrees of the AC waveform, with both results passing"}, {"id": "d", "text": "The RCD must physically eject the test plug upon successful tripping"}, {"id": "e", "text": "The measured earth fault loop impedance must automatically drop to zero Ohms during the test"}]', '["a", "c"]', 'VERIFIED. An RCD must clear a 1x fault within 300ms. Furthermore, because AC alternates, the test instrument must inject the fault at both the positive (0°) and negative (180°) half-cycles to ensure the internal coil responds correctly in both directions.', NULL, 3, NULL, '2026-05-12 13:49:54.773386+00', 'multiple_select');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('77185173-6609-5b3d-96d7-268818532613', '4485a268-25ec-58de-8df8-5fa3df330063', 'In a domestic TN-C-S electrical installation, what is the primary life-safety hazard if the street utility neutral conductor breaks (an ''Open PEN'' fault) and the installation lacks a functioning local earth electrode?', '[{"id": "a", "text": "The return current will be forced through the MEN link to the earth bar, causing the metallic chassis of all earthed appliances to become dangerously energized at mains voltage"}, {"id": "b", "text": "The installation''s RCDs will immediately trip and physically lock out until the grid is repaired"}, {"id": "c", "text": "The supply voltage will simply drop to 115V, slowing down motor loads but posing no shock risk"}, {"id": "d", "text": "The smart meter will automatically detect the voltage drop and disconnect the active phase"}]', '["a"]', 'VERIFIED. This is the exact reason local earth electrodes are legally mandated. If the street neutral drops, the MEN link bridges the neutral current to the earth system. Without a good electrode to sink that current into the ground, everything metal in the house becomes live at 230V.', NULL, 3, NULL, '2026-05-12 13:49:54.773386+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('3b1b335e-7237-5ee9-83aa-9357c474efa5', '33c66c01-f417-510d-be43-101e18e33a5d', 'Under the New Zealand Electricity Act 1992, which TWO of the following groups are legally permitted to carry out standard Prescribed Electrical Work (PEW)?', '[{"id": "a", "text": "Registered Electrical Workers holding a current practising licence"}, {"id": "b", "text": "Unlicensed individuals acting under the direct, active supervision of a registered and licensed electrical worker"}, {"id": "c", "text": "Registered plumbers, provided the electrical work is strictly limited to replacing water heating elements"}, {"id": "d", "text": "Any person holding a university Bachelor of Electrical Engineering degree"}, {"id": "e", "text": "Any property owner, provided the work is carried out on a rental property they personally manage"}]', '["a", "b"]', 'VERIFIED. PEW is strictly restricted to licensed electrical workers, or trainees/unlicensed individuals who are working under the explicit, direct supervision of someone who holds a license. Degrees and plumbing registrations do not grant PEW rights.', NULL, 3, NULL, '2026-05-12 13:49:54.773386+00', 'multiple_select');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('ced8a045-0495-530b-a37d-533badec9e88', '4b09cc13-dedd-58f5-880c-9d460f74562e', 'Which of the following best describes the primary safety function of an ''Isolation Transformer'' installed to supply a single socket-outlet in a hazardous testing environment?', '[{"id": "a", "text": "It electrically separates the secondary circuit from the primary earth, meaning a single phase-to-earth fault on the secondary side will not result in a completed circuit or a lethal shock"}, {"id": "b", "text": "It completely removes all voltage from the secondary circuit until a load is actively plugged in"}, {"id": "c", "text": "It steps the voltage down from 230V to 12V DC to ensure intrinsic safety"}, {"id": "d", "text": "It actively corrects the power factor of any appliance plugged into the socket"}]', '["a"]', 'VERIFIED. By having no physical connection to earth on the secondary winding, touching one of the live secondary wires while standing on the ground does not complete a circuit, preventing electrocution from a first fault.', NULL, 3, NULL, '2026-05-12 13:49:54.773386+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('0e147256-06ee-5195-9227-102f1abfa7f2', '1b3cf5db-12ef-59aa-9127-e3d6dcb35a2f', 'Under AS/NZS 3000 Section 6, what is the absolute minimum Ingress Protection (IP) rating required for any electrical equipment permanently installed within Zone 0 of a damp situation (e.g., completely submerged underwater inside a swimming pool)?', '[{"id": "a", "text": "IPX8"}, {"id": "b", "text": "IPX4"}, {"id": "c", "text": "IPX7"}, {"id": "d", "text": "IP56"}]', '["a"]', 'VERIFIED. Zone 0 (inside the basin/underwater) requires equipment to be continuously submerged. IPX7 only protects against temporary immersion. IPX8 is strictly required for continuous submersion.', NULL, 3, NULL, '2026-05-12 13:49:54.773386+00', 'single_choice');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('eebfbdb7-6111-570c-ac8b-e862c2f7353f', 'cf002c8c-36ac-50c7-a590-36ab31e09e40', 'A single-phase circuit has a maximum design load of 15A. The selected cable has a voltage drop constant (Vc) of 10.4 mV/A.m. If the installation''s maximum allowable voltage drop is 11.5 Volts, calculate the absolute maximum permitted route length of this cable in metres. Provide your answer to one decimal place.', NULL, '{"unit": "m", "answers": ["73.7"], "tolerance": 0.2}', 'VERIFIED. Rearranging the formula: L = (Vd x 1000) / (I x Vc). L = (11.5 x 1000) / (15 x 10.4). L = 11500 / 156 = 73.717 metres. Rounded to 73.7m.', NULL, 3, NULL, '2026-05-12 13:49:54.773386+00', 'exact_value');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('289961b8-335f-53e5-b87f-87dd405c8120', 'edfd8597-c616-5170-8a22-9ea0c3e26514', 'Under the New Zealand Electricity (Safety) Regulations 2010, which TWO of the following conditions must strictly be met before a newly altered electrical installation can be legally and safely re-energized?', '[{"id": "a", "text": "All mandatory dead tests (Earth Continuity, Insulation Resistance, Polarity) must be completed and pass the minimum standards"}, {"id": "b", "text": "The completed work must be formally certified with a signed Certificate of Compliance (CoC) and Electrical Safety Certificate (ESC)"}, {"id": "c", "text": "The local network utility provider must install a brand new smart meter"}, {"id": "d", "text": "The property owner must physically sign a liability waiver"}, {"id": "e", "text": "The installation must be run on generator power for 24 hours to ''burn in'' the new breakers"}]', '["a", "b"]', 'VERIFIED. The statutory requirement for enlivening is that the installation must be electrically safe (proven by dead testing) and legally certified (CoC/ESC) before the main switch is turned back on.', NULL, 3, NULL, '2026-05-12 13:49:54.773386+00', 'multiple_select');
INSERT INTO public.questions (id, topic_id, body, options, correct_answer, explanation, regulation_clause, difficulty, variants_of, created_at, question_type) VALUES ('9554d145-77b9-58d3-a5bc-b9c5959c77bd', 'ac388207-779c-5a46-a6e9-b556f0578f56', 'Under recent amendments to AS/NZS 3000, what is the primary technical purpose of installing an ''Arc Fault Detection Device'' (AFDD) on a final subcircuit?', '[{"id": "a", "text": "To detect low-level series or parallel arcing faults (e.g., from a crushed extension cord) that cause electrical fires but draw too little current to trip a standard MCB or RCD"}, {"id": "b", "text": "To detect and clear massive short-circuit currents faster than a High Rupturing Capacity (HRC) fuse"}, {"id": "c", "text": "To monitor the power factor of the circuit and automatically disconnect highly inductive motor loads"}, {"id": "d", "text": "To prevent the circuit''s total voltage drop from exceeding the 5% statutory limit"}]', '["a"]', 'VERIFIED. MCBs protect against overload. RCDs protect against earth leakage. AFDDs protect against micro-arcing (sparks across broken wires) which cause devastating fires but are invisible to MCBs and RCDs.', NULL, 3, NULL, '2026-05-12 13:49:54.773386+00', 'single_choice');
